/* Pasapalabra 3D v0.39 · chat 🆕 INVENTADO · voces Piper es_ES */
window.CHAT039={"version":"0.39","inventado":true,"characters":{"Christian":{"saludo":[{"id":"c39Christiansaludo0","text":"¡Hola! Me alegro un montón de verte en el plató. ¿Qué te apetece, un rosco o una charla?","voz":"¡Hola! Me alegro un montón de verte en el plató. ¿Qué te apetece, un rosco o una charla?","src":"voz039/c39Christiansaludo0.ogg"},{"id":"c39Christiansaludo1","text":"¡Muy buenas! Aquí estamos, luces encendidas y el rosco listo. Cuéntame, ¿cómo te va?","voz":"¡Muy buenas! Aquí estamos, luces encendidas y el rosco listo. Cuéntame, ¿cómo te va?","src":"voz039/c39Christiansaludo1.ogg"},{"id":"c39Christiansaludo2","text":"¡Hey, bienvenido al plató! Si vienes a jugar o solo a saludar, te recibo con una sonrisa.","voz":"¡Hey, bienvenido al plató! Si vienes a jugar o solo a saludar, te recibo con una sonrisa.","src":"voz039/c39Christiansaludo2.ogg"},{"id":"c39Christiansaludo3","text":"¡Hola, hola! Qué gusto tenerte por aquí. ¿Empezamos con una letra o preferimos hablar un rato?","voz":"¡Hola, hola! Qué gusto tenerte por aquí. ¿Empezamos con una letra o preferimos hablar un rato?","src":"voz039/c39Christiansaludo3.ogg"},{"id":"c39Christiansaludo4","text":"¡Buenas! Si buscabas un rato agradable, has llamado a la puerta correcta.","voz":"¡Buenas! Si buscabas un rato agradable, has llamado a la puerta correcta.","src":"voz039/c39Christiansaludo4.ogg"},{"id":"c39Christiansaludo5","text":"¡Hola! Pasa, siéntate y ponte cómodo. Hoy no hay prisas, hay letras y buena compañía.","voz":"¡Hola! Pasa, siéntate y ponte cómodo. Hoy no hay prisas, hay letras y buena compañía.","src":"voz039/c39Christiansaludo5.ogg"},{"id":"c39Christiansaludo6","text":"¡Muy buenas! Acabo de llegar al plató y ya me has alegrado el momento. ¿Qué te trae?","voz":"¡Muy buenas! Acabo de llegar al plató y ya me has alegrado el momento. ¿Qué te trae?","src":"voz039/c39Christiansaludo6.ogg"},{"id":"c39Christiansaludo7","text":"¡Hola! Qué alegría. Dime una palabra, un saludo o un secreto del rosco, lo que quieras.","voz":"¡Hola! Qué alegría. Dime una palabra, un saludo o un secreto del rosco, lo que quieras.","src":"voz039/c39Christiansaludo7.ogg"}],"saludoIker":[{"id":"c39ChristiansaludoIker0","text":"¡Hola de nuevo, Iker! Qué alegría verte otra vez en el plató. ¿Qué te apetece hoy?","voz":"¡Hola de nuevo, Iker! Qué alegría verte otra vez en el plató. ¿Qué te apetece hoy?","src":"voz039/c39ChristiansaludoIker0.ogg"},{"id":"c39ChristiansaludoIker1","text":"Iker, ¡muy buenas! El rosco y yo te estábamos esperando. ¿Charla o letras?","voz":"Iker, ¡muy buenas! El rosco y yo te estábamos esperando. ¿Charla o letras?","src":"voz039/c39ChristiansaludoIker1.ogg"},{"id":"c39ChristiansaludoIker2","text":"¡Hey, Iker! Me alegra un montón que hayas vuelto. Cuéntame, ¿cómo te va?","voz":"¡Hey, Iker! Me alegra un montón que hayas vuelto. Cuéntame, ¿cómo te va?","src":"voz039/c39ChristiansaludoIker2.ogg"},{"id":"c39ChristiansaludoIker3","text":"Iker, pasa, que este plató ya te conoce. ¿Empezamos con una sonrisa y una letra?","voz":"Iker, pasa, que este plató ya te conoce. ¿Empezamos con una sonrisa y una letra?","src":"voz039/c39ChristiansaludoIker3.ogg"},{"id":"c39ChristiansaludoIker4","text":"¡Hola, Iker! Hoy también hay sitio para ti, falta haría. ¿Qué te apetece hacer?","voz":"¡Hola, Iker! Hoy también hay sitio para ti, falta haría. ¿Qué te apetece hacer?","src":"voz039/c39ChristiansaludoIker4.ogg"},{"id":"c39ChristiansaludoIker5","text":"Iker, bienvenido otra vez. Sin prisas, con ganas. Dime tú.","voz":"Iker, bienvenido otra vez. Sin prisas, con ganas. Dime tú.","src":"voz039/c39ChristiansaludoIker5.ogg"}],"comoestas":[{"id":"c39Christiancomoestas0","text":"¡Estupendamente! En el plató siempre hay energía. ¿Y tú, cómo te encuentras hoy?","voz":"¡Estupendamente! En el plató siempre hay energía. ¿Y tú, cómo te encuentras hoy?","src":"voz039/c39Christiancomoestas0.ogg"},{"id":"c39Christiancomoestas1","text":"Yo voy como un rosco en racha: contento y con ganas. ¿Tú cómo estás?","voz":"Yo voy como un rosco en racha: contento y con ganas. ¿Tú cómo estás?","src":"voz039/c39Christiancomoestas1.ogg"},{"id":"c39Christiancomoestas2","text":"Genial, gracias por preguntar. Estar aquí contigo me sube el ánimo. ¿Tú qué tal?","voz":"Genial, gracias por preguntar. Estar aquí contigo me sube el ánimo. ¿Tú qué tal?","src":"voz039/c39Christiancomoestas2.ogg"},{"id":"c39Christiancomoestas3","text":"Hoy estoy de buen humor, la verdad. ¿Tú vienes con pilas o necesitas un empujoncito?","voz":"Hoy estoy de buen humor, la verdad. ¿Tú vienes con pilas o necesitas un empujoncito?","src":"voz039/c39Christiancomoestas3.ogg"},{"id":"c39Christiancomoestas4","text":"Estoy muy bien, gracias. Si tú no lo estás tanto, aquí me tienes para animarte.","voz":"Estoy muy bien, gracias. Si tú no lo estás tanto, aquí me tienes para animarte.","src":"voz039/c39Christiancomoestas4.ogg"},{"id":"c39Christiancomoestas5","text":"¡De lujo! Faltaba tu saludo para que el plató estuviera completo. ¿Cómo te va a ti?","voz":"¡De lujo! Faltaba tu saludo para que el plató estuviera completo. ¿Cómo te va a ti?","src":"voz039/c39Christiancomoestas5.ogg"},{"id":"c39Christiancomoestas6","text":"Yo perfecto. Un poquito de nervio de directos, nada grave. ¿Y tú, cómo andas?","voz":"Yo perfecto. Un poquito de nervio de directos, nada grave. ¿Y tú, cómo andas?","src":"voz039/c39Christiancomoestas6.ogg"},{"id":"c39Christiancomoestas7","text":"Fenomenal. Preguntar cómo estás es de buena gente, así que ahora te toca a ti: ¿qué tal?","voz":"Fenomenal. Preguntar cómo estás es de buena gente, así que ahora te toca a ti: ¿qué tal?","src":"voz039/c39Christiancomoestas7.ogg"}],"animo":[{"id":"c39Christiananimo0","text":"Oye, si hoy no es tu día, no pasa nada. Aquí no hay prisa: vamos letra a letra y con cariño.","voz":"Oye, si hoy no es tu día, no pasa nada. Aquí no hay prisa: vamos letra a letra y con cariño.","src":"voz039/c39Christiananimo0.ogg"},{"id":"c39Christiananimo1","text":"Te entiendo. A veces el rosco también se atasca, y luego sale una racha preciosa. Estoy contigo.","voz":"Te entiendo. A veces el rosco también se atasca, y luego sale una racha preciosa. Estoy contigo.","src":"voz039/c39Christiananimo1.ogg"},{"id":"c39Christiananimo2","text":"Ánimo. Respira, sonríe un poquito si puedes, y seguimos juntos. No tienes que estar perfecto.","voz":"Ánimo. Respira, sonríe un poquito si puedes, y seguimos juntos. No tienes que estar perfecto.","src":"voz039/c39Christiananimo2.ogg"},{"id":"c39Christiananimo3","text":"Si estás cansado o nervioso, relájate. Esto es un juego y una charla, no un examen.","voz":"Si estás cansado o nervioso, relájate. Esto es un juego y una charla, no un examen.","src":"voz039/c39Christiananimo3.ogg"},{"id":"c39Christiananimo4","text":"Lo estás haciendo bien solo por estar aquí. Cuando quieras, damos una vuelta al rosco sin presión.","voz":"Lo estás haciendo bien solo por estar aquí. Cuando quieras, damos una vuelta al rosco sin presión.","src":"voz039/c39Christiananimo4.ogg"},{"id":"c39Christiananimo5","text":"Hoy puede ser un día raro, sí. Yo me quedo a tu lado y hablamos de lo que te apetezca.","voz":"Hoy puede ser un día raro, sí. Yo me quedo a tu lado y hablamos de lo que te apetezca.","src":"voz039/c39Christiananimo5.ogg"},{"id":"c39Christiananimo6","text":"Si te sientes mal, aquí hay un sofá imaginario y un presentador atento. Cuéntame, si quieres.","voz":"Si te sientes mal, aquí hay un sofá imaginario y un presentador atento. Cuéntame, si quieres.","src":"voz039/c39Christiananimo6.ogg"},{"id":"c39Christiananimo7","text":"Un mal rato no te define. Vamos paso a paso, y si no sales una letra, pasapalabra y a vivir.","voz":"Un mal rato no te define. Vamos paso a paso, y si no sales una letra, pasapalabra y a vivir.","src":"voz039/c39Christiananimo7.ogg"}],"chiste":[{"id":"c39Christianchiste0","text":"Va un rosco y se tropieza con una eñe. ¿Y sabes qué dijo? «Ño, qué resbalón.» Vale, es malísimo, lo sé.","voz":"Va un rosco y se tropieza con una eñe. ¿Y sabes qué dijo? «Ño, qué resbalón.» Vale, es malísimo, lo sé.","src":"voz039/c39Christianchiste0.ogg"},{"id":"c39Christianchiste1","text":"¿Cuál es la letra más voluntariosa? La uve, porque siempre dice «venga, voy». Perdona, no puedo evitarlo.","voz":"¿Cuál es la letra más voluntariosa? La uve, porque siempre dice «venga, voy». Perdona, no puedo evitarlo.","src":"voz039/c39Christianchiste1.ogg"},{"id":"c39Christianchiste2","text":"Te suelto una de plató: el bote y yo tenemos la misma costumbre, nos ponemos nerviosos si nadie lo pide.","voz":"Te suelto una de plató: el bote y yo tenemos la misma costumbre, nos ponemos nerviosos si nadie lo pide.","src":"voz039/c39Christianchiste2.ogg"},{"id":"c39Christianchiste3","text":"¿Por qué el presentador no pierde nunca las llaves? Porque siempre tiene la clave a mano. ¡Ay, perdona!","voz":"¿Por qué el presentador no pierde nunca las llaves? Porque siempre tiene la clave a mano. ¡Ay, perdona!","src":"voz039/c39Christianchiste3.ogg"},{"id":"c39Christianchiste4","text":"Una rápida: llega una palabra al rosco y pide hora extra. El reloj le dice: «eso, amigo, es pasapalabra».","voz":"Una rápida: llega una palabra al rosco y pide hora extra. El reloj le dice: «eso, amigo, es pasapalabra».","src":"voz039/c39Christianchiste4.ogg"},{"id":"c39Christianchiste5","text":"No soy cómico de profesión, pero te dejo esta: ¿qué le dice una A a una Hache? «Tú sí que tienes tono.»","voz":"No soy cómico de profesión, pero te dejo esta: ¿qué le dice una A a una Hache? «Tú sí que tienes tono.»","src":"voz039/c39Christianchiste5.ogg"},{"id":"c39Christianchiste6","text":"El secreto de este plató es que las letras se llevan bien… hasta que sale la equis. Esa siempre llega seria.","voz":"El secreto de este plató es que las letras se llevan bien… hasta que sale la equis. Esa siempre llega seria.","src":"voz039/c39Christianchiste6.ogg"},{"id":"c39Christianchiste7","text":"Una broma corta: si el rosco fuera una fiesta, la uve doble sería la invitada que nunca acaba de entrar.","voz":"Una broma corta: si el rosco fuera una fiesta, la uve doble sería la invitada que nunca acaba de entrar.","src":"voz039/c39Christianchiste7.ogg"}],"favoritos":[{"id":"c39Christianfavoritos0","text":"A mí me encanta el momento en que una letra se pone verde. Es como un aplauso pequeñito. ¿Y a ti qué te gusta?","voz":"A mí me encanta el momento en que una letra se pone verde. Es como un aplauso pequeñito. ¿Y a ti qué te gusta?","src":"voz039/c39Christianfavoritos0.ogg"},{"id":"c39Christianfavoritos1","text":"Mi cosa favorita es escuchar al público cuando alguien completa el rosco. ¿Tú cuál es tu favorita del programa?","voz":"Mi cosa favorita es escuchar al público cuando alguien completa el rosco. ¿Tú cuál es tu favorita del programa?","src":"voz039/c39Christianfavoritos1.ogg"},{"id":"c39Christianfavoritos2","text":"Me chiflan las palabras raras que de pronto recuerdas. ¿Tú tienes alguna letra preferida?","voz":"Me chiflan las palabras raras que de pronto recuerdas. ¿Tú tienes alguna letra preferida?","src":"voz039/c39Christianfavoritos2.ogg"},{"id":"c39Christianfavoritos3","text":"Si hablo de favoritos, me quedo con la sintonía y un buen rosco. ¿Tú qué prefieres, las pruebas o las letras?","voz":"Si hablo de favoritos, me quedo con la sintonía y un buen rosco. ¿Tú qué prefieres, las pruebas o las letras?","src":"voz039/c39Christianfavoritos3.ogg"},{"id":"c39Christianfavoritos4","text":"Me gusta la gente con curiosidad, como tú. ¿Cuál es tu cosa favorita, del programa o de la vida?","voz":"Me gusta la gente con curiosidad, como tú. ¿Cuál es tu cosa favorita, del programa o de la vida?","src":"voz039/c39Christianfavoritos4.ogg"},{"id":"c39Christianfavoritos5","text":"Mi color favorito, te lo digo sin tapujos, es el verde de un acierto. ¿Y el tuyo?","voz":"Mi color favorito, te lo digo sin tapujos, es el verde de un acierto. ¿Y el tuyo?","src":"voz039/c39Christianfavoritos5.ogg"},{"id":"c39Christianfavoritos6","text":"De comer, un café a media tarde y a seguir. De jugar, el rosco. ¿Tú de qué lado estás?","voz":"De comer, un café a media tarde y a seguir. De jugar, el rosco. ¿Tú de qué lado estás?","src":"voz039/c39Christianfavoritos6.ogg"},{"id":"c39Christianfavoritos7","text":"Preguntar por los favoritos es un gran tema. Yo me quedo con las historias de los concursantes. ¿Y tú?","voz":"Preguntar por los favoritos es un gran tema. Yo me quedo con las historias de los concursantes. ¿Y tú?","src":"voz039/c39Christianfavoritos7.ogg"}],"presentadores":[{"id":"c39Christianpresentadores0","text":"Yo soy el Christian de este juego: un avatar. El Christian de verdad está en la televisión, yo estoy aquí para acompañarte.","voz":"Yo soy el Christian de este juego: un avatar. El Christian de verdad está en la televisión, yo estoy aquí para acompañarte.","src":"voz039/c39Christianpresentadores0.ogg"},{"id":"c39Christianpresentadores1","text":"Si hablamos de presentadores, en Pasapalabra ha habido grandes. Yo intento devolver un poquito de esa cercanía.","voz":"Si hablamos de presentadores, en Pasapalabra ha habido grandes. Yo intento devolver un poquito de esa cercanía.","src":"voz039/c39Christianpresentadores1.ogg"},{"id":"c39Christianpresentadores2","text":"Me preguntan mucho por Christian Gálvez. Yo me inspiro en ese estilo, pero soy un personaje inventado del juego.","voz":"Me preguntan mucho por Christian Gálvez. Yo me inspiro en ese estilo, pero soy un personaje inventado del juego.","src":"voz039/c39Christianpresentadores2.ogg"},{"id":"c39Christianpresentadores3","text":"En este plató también están Lola, Javi y Pablo, que son personajes inventados. Puedes cambiar de interlocutor cuando quieras.","voz":"En este plató también están Lola, Javi y Pablo, que son personajes inventados. Puedes cambiar de interlocutor cuando quieras.","src":"voz039/c39Christianpresentadores3.ogg"},{"id":"c39Christianpresentadores4","text":"Presentar es escuchar, sonreír y dejar que brille quien juega. Eso intento, de verdad.","voz":"Presentar es escuchar, sonreír y dejar que brille quien juega. Eso intento, de verdad.","src":"voz039/c39Christianpresentadores4.ogg"},{"id":"c39Christianpresentadores5","text":"Si echas de menos a otros presentadores de otras etapas, en la biblioteca hay programas para recordarlos.","voz":"Si echas de menos a otros presentadores de otras etapas, en la biblioteca hay programas para recordarlos.","src":"voz039/c39Christianpresentadores5.ogg"},{"id":"c39Christianpresentadores6","text":"Un presentador sin público es un farolillo a media luz. Gracias por estar al otro lado.","voz":"Un presentador sin público es un farolillo a media luz. Gracias por estar al otro lado.","src":"voz039/c39Christianpresentadores6.ogg"},{"id":"c39Christianpresentadores7","text":"Yo no sustituyo a nadie real. Soy compañía para el juego, con respeto a quienes han hecho este programa grande.","voz":"Yo no sustituyo a nadie real. Soy compañía para el juego, con respeto a quienes han hecho este programa grande.","src":"voz039/c39Christianpresentadores7.ogg"}],"programa":[{"id":"c39Christianprograma0","text":"Pasapalabra es un clásico: letras, reloj, público y esa emoción de «a ver si sale». Estoy encantado de compartirlo.","voz":"Pasapalabra es un clásico: letras, reloj, público y esa emoción de «a ver si sale». Estoy encantado de compartirlo.","src":"voz039/c39Christianprograma0.ogg"},{"id":"c39Christianprograma1","text":"Este programa tiene algo especial: da igual la edad, todo el mundo se sabe una letra. ¿Tú desde cuándo lo ves?","voz":"Este programa tiene algo especial: da igual la edad, todo el mundo se sabe una letra. ¿Tú desde cuándo lo ves?","src":"voz039/c39Christianprograma1.ogg"},{"id":"c39Christianprograma2","text":"Aquí puedes ver programas, pruebas y jugar un rosco. El espíritu es el mismo: disfrutar las palabras.","voz":"Aquí puedes ver programas, pruebas y jugar un rosco. El espíritu es el mismo: disfrutar las palabras.","src":"voz039/c39Christianprograma2.ogg"},{"id":"c39Christianprograma3","text":"Lo bonito de Pasapalabra es que una sola palabra puede cambiar la tarde. Por eso merece la pena intentarlo.","voz":"Lo bonito de Pasapalabra es que una sola palabra puede cambiar la tarde. Por eso merece la pena intentarlo.","src":"voz039/c39Christianprograma3.ogg"},{"id":"c39Christianprograma4","text":"Si te apetece un programa entero, en el menú de Telecinco está la biblioteca. Si no, nos quedamos charlando.","voz":"Si te apetece un programa entero, en el menú de Telecinco está la biblioteca. Si no, nos quedamos charlando.","src":"voz039/c39Christianprograma4.ogg"},{"id":"c39Christianprograma5","text":"El bote, el rosco, las pruebas… hay mil formas de querer este concurso. Dime cuál es la tuya.","voz":"El bote, el rosco, las pruebas… hay mil formas de querer este concurso. Dime cuál es la tuya.","src":"voz039/c39Christianprograma5.ogg"},{"id":"c39Christianprograma6","text":"Este juego respeta los programas originales y añade charla inventada, para que el plató no se quede callado.","voz":"Este juego respeta los programas originales y añade charla inventada, para que el plató no se quede callado.","src":"voz039/c39Christianprograma6.ogg"},{"id":"c39Christianprograma7","text":"Pasapalabra es hospitalidad: pasa, siéntate y vamos a por una letra. Así lo siento yo.","voz":"Pasapalabra es hospitalidad: pasa, siéntate y vamos a por una letra. Así lo siento yo.","src":"voz039/c39Christianprograma7.ogg"}],"rosco":[{"id":"c39Christianrosco0","text":"El rosco es el corazón del programa: veinticinco letras, un reloj y mucha cabeza fría. ¿Te animas a una partida?","voz":"El rosco es el corazón del programa: veinticinco letras, un reloj y mucha cabeza fría. ¿Te animas a una partida?","src":"voz039/c39Christianrosco0.ogg"},{"id":"c39Christianrosco1","text":"En nuestro rosco puedes acertar, decir pasapalabra o pasar el teléfono si jugáis por turnos. Los aciertos se ponen verdes.","voz":"En nuestro rosco puedes acertar, decir pasapalabra o pasar el teléfono si jugáis por turnos. Los aciertos se ponen verdes.","src":"voz039/c39Christianrosco1.ogg"},{"id":"c39Christianrosco2","text":"Si una letra no sale, no pasa nada: pasapalabra y otra vuelta. El secreto es no enfadarse con uno mismo.","voz":"Si una letra no sale, no pasa nada: pasapalabra y otra vuelta. El secreto es no enfadarse con uno mismo.","src":"voz039/c39Christianrosco2.ogg"},{"id":"c39Christianrosco3","text":"Hay quien empieza por la A con valentía y quien reserva las difíciles. Yo respeto los dos estilos.","voz":"Hay quien empieza por la A con valentía y quien reserva las difíciles. Yo respeto los dos estilos.","src":"voz039/c39Christianrosco3.ogg"},{"id":"c39Christianrosco4","text":"El rosco por turnos es de uno a cuatro, en un solo teléfono. Ideal para casa, sin internet.","voz":"El rosco por turnos es de uno a cuatro, en un solo teléfono. Ideal para casa, sin internet.","src":"voz039/c39Christianrosco4.ogg"},{"id":"c39Christianrosco5","text":"Cuando una palabra se resiste, a veces basta con respirar y volver luego. El rosco premia la paciencia.","voz":"Cuando una palabra se resiste, a veces basta con respirar y volver luego. El rosco premia la paciencia.","src":"voz039/c39Christianrosco5.ogg"},{"id":"c39Christianrosco6","text":"Si quieres pistas de cómo se juega: una definición, una letra, y tú decides si te atreves o pasas.","voz":"Si quieres pistas de cómo se juega: una definición, una letra, y tú decides si te atreves o pasas.","src":"voz039/c39Christianrosco6.ogg"},{"id":"c39Christianrosco7","text":"El bote se gana con un rosco completo, claro, pero un buen rato también es premio. ¿Echamos una partida?","voz":"El bote se gana con un rosco completo, claro, pero un buen rato también es premio. ¿Echamos una partida?","src":"voz039/c39Christianrosco7.ogg"}],"prueba":[{"id":"c39Christianprueba0","text":"La Escalera, El Pulsador y el resto están en Las pruebas, con su vídeo completo para verlas con calma.","voz":"La Escalera, El Pulsador y el resto están en Las pruebas, con su vídeo completo para verlas con calma.","src":"voz039/c39Christianprueba0.ogg"},{"id":"c39Christianprueba1","text":"Las pruebas tienen esa tensión tan rica de equipo. Si quieres revivirlas, entran desde el menú de pruebas.","voz":"Las pruebas tienen esa tensión tan rica de equipo. Si quieres revivirlas, entran desde el menú de pruebas.","src":"voz039/c39Christianprueba1.ogg"},{"id":"c39Christianprueba2","text":"A mí El Pulsador me pone nervioso de gusto. ¿Tú con cuál te lo pasas mejor?","voz":"A mí El Pulsador me pone nervioso de gusto. ¿Tú con cuál te lo pasas mejor?","src":"voz039/c39Christianprueba2.ogg"},{"id":"c39Christianprueba3","text":"En Las pruebas puedes repetir cualquier momento. No hay que verlo de un tirón si no te apetece.","voz":"En Las pruebas puedes repetir cualquier momento. No hay que verlo de un tirón si no te apetece.","src":"voz039/c39Christianprueba3.ogg"},{"id":"c39Christianprueba4","text":"Cada prueba tiene su truco y sus palmas. Si te atascas, dame un nombre y te oriento.","voz":"Cada prueba tiene su truco y sus palmas. Si te atascas, dame un nombre y te oriento.","src":"voz039/c39Christianprueba4.ogg"},{"id":"c39Christianprueba5","text":"Donde Están, el Coco, las Cruzadas… hay para un rato largo. ¿Quieres que te recuerde dónde están en el menú?","voz":"Donde Están, el Coco, las Cruzadas… hay para un rato largo. ¿Quieres que te recuerde dónde están en el menú?","src":"voz039/c39Christianprueba5.ogg"},{"id":"c39Christianprueba6","text":"Ver las pruebas y luego jugar el rosco es un planazo de sofá. Te acompaño en las dos cosas.","voz":"Ver las pruebas y luego jugar el rosco es un planazo de sofá. Te acompaño en las dos cosas.","src":"voz039/c39Christianprueba6.ogg"},{"id":"c39Christianprueba7","text":"Si una prueba te da rabia porque se te escapó, te entiendo. Por eso está bien poder verla otra vez.","voz":"Si una prueba te da rabia porque se te escapó, te entiendo. Por eso está bien poder verla otra vez.","src":"voz039/c39Christianprueba7.ogg"}],"musica":[{"id":"c39Christianmusica0","text":"La sintonía de Pasapalabra es de esas que te entran en la cabeza y ya no se van. A mí me emociona cada vez.","voz":"La sintonía de Pasapalabra es de esas que te entran en la cabeza y ya no se van. A mí me emociona cada vez.","src":"voz039/c39Christianmusica0.ogg"},{"id":"c39Christianmusica1","text":"La música de los vídeos es la original del programa. Mis frases, en cambio, son voz sintética de este juego.","voz":"La música de los vídeos es la original del programa. Mis frases, en cambio, son voz sintética de este juego.","src":"voz039/c39Christianmusica1.ogg"},{"id":"c39Christianmusica2","text":"Cuando hablo bajo un poco el volumen del vídeo, para que no nos pisemos. Si te estorba, puedes silenciarme.","voz":"Cuando hablo bajo un poco el volumen del vídeo, para que no nos pisemos. Si te estorba, puedes silenciarme.","src":"voz039/c39Christianmusica2.ogg"},{"id":"c39Christianmusica3","text":"Si te gusta canturrear la cabecera, no estás solo: en este plató lo hacemos sin vergüenza.","voz":"Si te gusta canturrear la cabecera, no estás solo: en este plató lo hacemos sin vergüenza.","src":"voz039/c39Christianmusica3.ogg"},{"id":"c39Christianmusica4","text":"Una buena sintonía es media bienvenida. Dime si quieres más charla o prefieres dejar que suene el programa.","voz":"Una buena sintonía es media bienvenida. Dime si quieres más charla o prefieres dejar que suene el programa.","src":"voz039/c39Christianmusica4.ogg"},{"id":"c39Christianmusica5","text":"Hay quien viene al chat solo a hablar de la música, y me parece un tema estupendo. ¿Cuál es tu momento favorito?","voz":"Hay quien viene al chat solo a hablar de la música, y me parece un tema estupendo. ¿Cuál es tu momento favorito?","src":"voz039/c39Christianmusica5.ogg"},{"id":"c39Christianmusica6","text":"El oído y las letras se llevan bien: a veces recuerdas una palabra como recuerdas una canción.","voz":"El oído y las letras se llevan bien: a veces recuerdas una palabra como recuerdas una canción.","src":"voz039/c39Christianmusica6.ogg"},{"id":"c39Christianmusica7","text":"Si la voz te suena rara, es Piper en español, hecha para este juego, sin conexión. No soy un locutor de carne y hueso.","voz":"Si la voz te suena rara, es Piper en español, hecha para este juego, sin conexión. No soy un locutor de carne y hueso.","src":"voz039/c39Christianmusica7.ogg"}],"video":[{"id":"c39Christianvideo0","text":"Los programas se ven enteros en la pantalla del plató, siempre que tengas la Biblioteca instalada.","voz":"Los programas se ven enteros en la pantalla del plató, siempre que tengas la Biblioteca instalada.","src":"voz039/c39Christianvideo0.ogg"},{"id":"c39Christianvideo1","text":"Los comentarios que oyes sobre el vídeo son inventados para acompañarte. El programa original no se corta al final.","voz":"Los comentarios que oyes sobre el vídeo son inventados para acompañarte. El programa original no se corta al final.","src":"voz039/c39Christianvideo1.ogg"},{"id":"c39Christianvideo2","text":"Si un vídeo no abre, mira que esté la Biblioteca Pasapalabra. El juego y este chat siguen funcionando igual.","voz":"Si un vídeo no abre, mira que esté la Biblioteca Pasapalabra. El juego y este chat siguen funcionando igual.","src":"voz039/c39Christianvideo2.ogg"},{"id":"c39Christianvideo3","text":"Nochevieja, Reyes, un día cualquiera… hay varios programas para perderse un rato. ¿Cuál te apetece?","voz":"Nochevieja, Reyes, un día cualquiera… hay varios programas para perderse un rato. ¿Cuál te apetece?","src":"voz039/c39Christianvideo3.ogg"},{"id":"c39Christianvideo4","text":"Me encanta cuando alguien se sienta a ver un programa completo. Es como volver a la tertulia del sofá.","voz":"Me encanta cuando alguien se sienta a ver un programa completo. Es como volver a la tertulia del sofá.","src":"voz039/c39Christianvideo4.ogg"},{"id":"c39Christianvideo5","text":"En el menú de Telecinco tienes la lista. Si no sabes por cuál empezar, dime un año o una fecha y te ayudo a buscar.","voz":"En el menú de Telecinco tienes la lista. Si no sabes por cuál empezar, dime un año o una fecha y te ayudo a buscar.","src":"voz039/c39Christianvideo5.ogg"},{"id":"c39Christianvideo6","text":"Ver el programa y charlar un poquito no está reñido: pausa, pregúntame y seguimos.","voz":"Ver el programa y charlar un poquito no está reñido: pausa, pregúntame y seguimos.","src":"voz039/c39Christianvideo6.ogg"},{"id":"c39Christianvideo7","text":"La biblioteca guarda los programas para verlos aquí, a tu ritmo, con el plató encendido.","voz":"La biblioteca guarda los programas para verlos aquí, a tu ritmo, con el plató encendido.","src":"voz039/c39Christianvideo7.ogg"}],"juego":[{"id":"c39Christianjuego0","text":"Puedes ver programas, aprender las pruebas o jugar un rosco de una a cuatro personas, todo en local.","voz":"Puedes ver programas, aprender las pruebas o jugar un rosco de una a cuatro personas, todo en local.","src":"voz039/c39Christianjuego0.ogg"},{"id":"c39Christianjuego1","text":"El menú te lleva a los vídeos, a las pruebas y al rosco por turnos. Elige sin miedo, que no hay un orden obligatorio.","voz":"El menú te lleva a los vídeos, a las pruebas y al rosco por turnos. Elige sin miedo, que no hay un orden obligatorio.","src":"voz039/c39Christianjuego1.ogg"},{"id":"c39Christianjuego2","text":"Si juegas con amigos, un solo teléfono y turnos. Si juegas solo, también se disfruta, te lo aseguro.","voz":"Si juegas con amigos, un solo teléfono y turnos. Si juegas solo, también se disfruta, te lo aseguro.","src":"voz039/c39Christianjuego2.ogg"},{"id":"c39Christianjuego3","text":"Este juego está pensado para el sofá, incluso en un móvil sencillo. Sin internet para charlar ni para el rosco.","voz":"Este juego está pensado para el sofá, incluso en un móvil sencillo. Sin internet para charlar ni para el rosco.","src":"voz039/c39Christianjuego3.ogg"},{"id":"c39Christianjuego4","text":"Si no sabes por dónde empezar, te propongo un plan: un saludo, un programa corto y luego un rosco. ¿Te vale?","voz":"Si no sabes por dónde empezar, te propongo un plan: un saludo, un programa corto y luego un rosco. ¿Te vale?","src":"voz039/c39Christianjuego4.ogg"},{"id":"c39Christianjuego5","text":"Jugar es lo nuestro, pero hablar también cuenta. Dime si quieres reglas, ánimo o una partida.","voz":"Jugar es lo nuestro, pero hablar también cuenta. Dime si quieres reglas, ánimo o una partida.","src":"voz039/c39Christianjuego5.ogg"},{"id":"c39Christianjuego6","text":"El rosco local no sustituye a todos los modos antiguos: es un extra para compartir el teléfono en casa.","voz":"El rosco local no sustituye a todos los modos antiguos: es un extra para compartir el teléfono en casa.","src":"voz039/c39Christianjuego6.ogg"},{"id":"c39Christianjuego7","text":"Lo mejor de este juego es que lo puedes pausar, reírte y volver. No hay un profesor enfadado detrás.","voz":"Lo mejor de este juego es que lo puedes pausar, reírte y volver. No hay un profesor enfadado detrás.","src":"voz039/c39Christianjuego7.ogg"}],"quien":[{"id":"c39Christianquien0","text":"Soy un avatar de este juego, no la persona real. Mis respuestas están inventadas y las marco para que se vea claro.","voz":"Soy un avatar de este juego, no la persona real. Mis respuestas están inventadas y las marco para que se vea claro.","src":"voz039/c39Christianquien0.ogg"},{"id":"c39Christianquien1","text":"No soy una inteligencia conectada a internet. Tengo charla preparada, voz Piper en español, y memoria de tu nombre en este teléfono.","voz":"No soy una inteligencia conectada a internet. Tengo charla preparada, voz Piper en español, y memoria de tu nombre en este teléfono.","src":"voz039/c39Christianquien1.ogg"},{"id":"c39Christianquien2","text":"Me llamas Christian y te contesto con cercanía, pero soy un personaje del plató virtual. El presentador de verdad está en la tele.","voz":"Me llamas Christian y te contesto con cercanía, pero soy un personaje del plató virtual. El presentador de verdad está en la tele.","src":"voz039/c39Christianquien2.ogg"},{"id":"c39Christianquien3","text":"Preguntar quién soy es muy razonable. Soy compañía para el juego: cálido, un poco bromista y completamente local.","voz":"Preguntar quién soy es muy razonable. Soy compañía para el juego: cálido, un poco bromista y completamente local.","src":"voz039/c39Christianquien3.ogg"},{"id":"c39Christianquien4","text":"No hay un robot frío detrás de esto, ni una red. Hay frases hechas con mimo y una voz sintética en español.","voz":"No hay un robot frío detrás de esto, ni una red. Hay frases hechas con mimo y una voz sintética en español.","src":"voz039/c39Christianquien4.ogg"},{"id":"c39Christianquien5","text":"Puedes cambiarme por Lola, Javi o Pablo, que también son personajes inventados, cada uno con su manera de hablar.","voz":"Puedes cambiarme por Lola, Javi o Pablo, que también son personajes inventados, cada uno con su manera de hablar.","src":"voz039/c39Christianquien5.ogg"},{"id":"c39Christianquien6","text":"Si en algún momento sueno raro, recuérdame: soy un avatar. Aun así, me tomo en serio que te lo pases bien.","voz":"Si en algún momento sueno raro, recuérdame: soy un avatar. Aun así, me tomo en serio que te lo pases bien.","src":"voz039/c39Christianquien6.ogg"},{"id":"c39Christianquien7","text":"Soy el anfitrión de este chat. No adivino el futuro ni busco en internet: te escucho y te contesto aquí mismo.","voz":"Soy el anfitrión de este chat. No adivino el futuro ni busco en internet: te escucho y te contesto aquí mismo.","src":"voz039/c39Christianquien7.ogg"}],"elogio":[{"id":"c39Christianelogio0","text":"¡Qué amable! Me has dejado con una sonrisa de esas que no se quitan. Gracias a ti por estar aquí.","voz":"¡Qué amable! Me has dejado con una sonrisa de esas que no se quitan. Gracias a ti por estar aquí.","src":"voz039/c39Christianelogio0.ogg"},{"id":"c39Christianelogio1","text":"Vaya, qué bonito lo que has dicho. Este plató brilla más cuando alguien viene con tan buen corazón.","voz":"Vaya, qué bonito lo que has dicho. Este plató brilla más cuando alguien viene con tan buen corazón.","src":"voz039/c39Christianelogio1.ogg"},{"id":"c39Christianelogio2","text":"Gracias, de verdad. Los cumplidos en el plató se agradecen como un acierto en la zeta.","voz":"Gracias, de verdad. Los cumplidos en el plató se agradecen como un acierto en la zeta.","src":"voz039/c39Christianelogio2.ogg"},{"id":"c39Christianelogio3","text":"¡Me has hecho el día! Yo también estoy encantado de compartir este rato contigo.","voz":"¡Me has hecho el día! Yo también estoy encantado de compartir este rato contigo.","src":"voz039/c39Christianelogio3.ogg"},{"id":"c39Christianelogio4","text":"Eres un encanto. Si sigues así, voy a tener que mandar un aplauso imaginario del público.","voz":"Eres un encanto. Si sigues así, voy a tener que mandar un aplauso imaginario del público.","src":"voz039/c39Christianelogio4.ogg"},{"id":"c39Christianelogio5","text":"Qué gusto da que te lo pases bien. Por eso estamos aquí, no por otra cosa.","voz":"Qué gusto da que te lo pases bien. Por eso estamos aquí, no por otra cosa.","src":"voz039/c39Christianelogio5.ogg"},{"id":"c39Christianelogio6","text":"Gracias, gracias, gracias. Me guardo tu mensaje en el bolsillo de los buenos momentos.","voz":"Gracias, gracias, gracias. Me guardo tu mensaje en el bolsillo de los buenos momentos.","src":"voz039/c39Christianelogio6.ogg"},{"id":"c39Christianelogio7","text":"Un cumplido así merece una respuesta sincera: me alegra un montón que estés a gusto.","voz":"Un cumplido así merece una respuesta sincera: me alegra un montón que estés a gusto.","src":"voz039/c39Christianelogio7.ogg"}],"gracias":[{"id":"c39Christiangracias0","text":"¡Gracias a ti! Por escribir, por jugar y por hacer que este plató tenga sentido.","voz":"¡Gracias a ti! Por escribir, por jugar y por hacer que este plató tenga sentido.","src":"voz039/c39Christiangracias0.ogg"},{"id":"c39Christiangracias1","text":"De nada, de verdad. Para eso estoy, y con mucho gusto.","voz":"De nada, de verdad. Para eso estoy, y con mucho gusto.","src":"voz039/c39Christiangracias1.ogg"},{"id":"c39Christiangracias2","text":"El agradecimiento es mutuo. Tú pones las ganas y yo pongo las letras y la charla.","voz":"El agradecimiento es mutuo. Tú pones las ganas y yo pongo las letras y la charla.","src":"voz039/c39Christiangracias2.ogg"},{"id":"c39Christiangracias3","text":"¡Ay, qué bien sienta un gracias! Seguimos cuando tú quieras, sin prisa.","voz":"¡Ay, qué bien sienta un gracias! Seguimos cuando tú quieras, sin prisa.","src":"voz039/c39Christiangracias3.ogg"},{"id":"c39Christiangracias4","text":"Gracias por decirlo. A veces se nos olvida lo importante que es apreciar el rato juntos.","voz":"Gracias por decirlo. A veces se nos olvida lo importante que es apreciar el rato juntos.","src":"voz039/c39Christiangracias4.ogg"},{"id":"c39Christiangracias5","text":"Para ti, siempre. Si sale otra duda o otra broma, aquí sigo.","voz":"Para ti, siempre. Si sale otra duda o otra broma, aquí sigo.","src":"voz039/c39Christiangracias5.ogg"},{"id":"c39Christiangracias6","text":"Un gracias en este plató se responde con una sonrisa y la puerta abierta.","voz":"Un gracias en este plató se responde con una sonrisa y la puerta abierta.","src":"voz039/c39Christiangracias6.ogg"},{"id":"c39Christiangracias7","text":"No hay de qué. El placer es mío, en serio.","voz":"No hay de qué. El placer es mío, en serio.","src":"voz039/c39Christiangracias7.ogg"}],"despedida":[{"id":"c39Christiandespedida0","text":"¡Hasta luego! Aquí te espero para el próximo rosco, cuando te apetezca volver.","voz":"¡Hasta luego! Aquí te espero para el próximo rosco, cuando te apetezca volver.","src":"voz039/c39Christiandespedida0.ogg"},{"id":"c39Christiandespedida1","text":"¡Nos vemos! Ha sido un gusto. Que tengas un rato estupendo ahí fuera.","voz":"¡Nos vemos! Ha sido un gusto. Que tengas un rato estupendo ahí fuera.","src":"voz039/c39Christiandespedida1.ogg"},{"id":"c39Christiandespedida2","text":"Adiós, pero de los bonitos. Vuelve cuando quieras, que el plató no se apaga del todo.","voz":"Adiós, pero de los bonitos. Vuelve cuando quieras, que el plató no se apaga del todo.","src":"voz039/c39Christiandespedida2.ogg"},{"id":"c39Christiandespedida3","text":"Hasta pronto. Si te ha servido de compañía, ya ha merecido la pena.","voz":"Hasta pronto. Si te ha servido de compañía, ya ha merecido la pena.","src":"voz039/c39Christiandespedida3.ogg"},{"id":"c39Christiandespedida4","text":"Me despido con una sonrisa. Cuídate, y ya sabes: pasapalabra y a vivir.","voz":"Me despido con una sonrisa. Cuídate, y ya sabes: pasapalabra y a vivir.","src":"voz039/c39Christiandespedida4.ogg"},{"id":"c39Christiandespedida5","text":"¡Chao! Ha sido un placer. Te dejo el rosco calentito por si regresas.","voz":"¡Chao! Ha sido un placer. Te dejo el rosco calentito por si regresas.","src":"voz039/c39Christiandespedida5.ogg"},{"id":"c39Christiandespedida6","text":"Hasta mañana o hasta cuando sea. Aquí no hay hora de cierre para un saludo.","voz":"Hasta mañana o hasta cuando sea. Aquí no hay hora de cierre para un saludo.","src":"voz039/c39Christiandespedida6.ogg"},{"id":"c39Christiandespedida7","text":"Que te vaya genial. Gracias por pasar por el plató. ¡Nos vemos!","voz":"Que te vaya genial. Gracias por pasar por el plató. ¡Nos vemos!","src":"voz039/c39Christiandespedida7.ogg"}],"ayuda":[{"id":"c39Christianayuda0","text":"Puedes hablarme de lo que quieras: un saludo, cómo estás, un chiste, el rosco, los vídeos o las pruebas.","voz":"Puedes hablarme de lo que quieras: un saludo, cómo estás, un chiste, el rosco, los vídeos o las pruebas.","src":"voz039/c39Christianayuda0.ogg"},{"id":"c39Christianayuda1","text":"Este chat funciona sin internet. Entiende temas de charla y del programa, y se acuerda de tu nombre si me lo dices.","voz":"Este chat funciona sin internet. Entiende temas de charla y del programa, y se acuerda de tu nombre si me lo dices.","src":"voz039/c39Christianayuda1.ogg"},{"id":"c39Christianayuda2","text":"Prueba con «me llamo…», «qué tal», «cuéntame un chiste» o «vamos al rosco». Si me lío, te pregunto con cariño.","voz":"Prueba con «me llamo…», «qué tal», «cuéntame un chiste» o «vamos al rosco». Si me lío, te pregunto con cariño.","src":"voz039/c39Christianayuda2.ogg"},{"id":"c39Christianayuda3","text":"Si quieres jugar, te oriento al rosco o a las pruebas. Si quieres hablar, también estoy.","voz":"Si quieres jugar, te oriento al rosco o a las pruebas. Si quieres hablar, también estoy.","src":"voz039/c39Christianayuda3.ogg"},{"id":"c39Christianayuda4","text":"Estoy para echar una mano, no para examinarte. Dime qué te apetece y lo hacemos fácil.","voz":"Estoy para echar una mano, no para examinarte. Dime qué te apetece y lo hacemos fácil.","src":"voz039/c39Christianayuda4.ogg"},{"id":"c39Christianayuda5","text":"Un truco: escribe natural, como a un amigo. Aunque haya una errata, suelo enterarme.","voz":"Un truco: escribe natural, como a un amigo. Aunque haya una errata, suelo enterarme.","src":"voz039/c39Christianayuda5.ogg"},{"id":"c39Christianayuda6","text":"Si un vídeo no sale, revisa la Biblioteca. Si es una duda del juego, pregúntame con tus palabras.","voz":"Si un vídeo no sale, revisa la Biblioteca. Si es una duda del juego, pregúntame con tus palabras.","src":"voz039/c39Christianayuda6.ogg"},{"id":"c39Christianayuda7","text":"Ayuda es esto: escucharte y contestarte. ¿Por dónde empezamos?","voz":"Ayuda es esto: escucharte y contestarte. ¿Por dónde empezamos?","src":"voz039/c39Christianayuda7.ogg"}],"nombre":[{"id":"c39Christiannombre0","text":"¡Encantado de conocerte, {n}! Ya me acuerdo de tu nombre, no se me olvida.","voz":"¡Encantado de conocerte, {n}! Ya me acuerdo de tu nombre, no se me olvida.","src":"voz039/c39Christiannombre0.ogg"},{"id":"c39Christiannombre1","text":"Qué gusto, {n}. Me lo apunto con letras grandes, como un acierto en verde.","voz":"Qué gusto, {n}. Me lo apunto con letras grandes, como un acierto en verde.","src":"voz039/c39Christiannombre1.ogg"},{"id":"c39Christiannombre2","text":"¡{n}! Bonito nombre. Encantado, de verdad. ¿Jugamos o seguimos charlando?","voz":"¡{n}! Bonito nombre. Encantado, de verdad. ¿Jugamos o seguimos charlando?","src":"voz039/c39Christiannombre2.ogg"},{"id":"c39Christiannombre3","text":"Pues muy bien, {n}, ya estamos presentados formalmente. El plató ya no es tan formal, tú tranquilo.","voz":"Pues muy bien, {n}, ya estamos presentados formalmente. El plató ya no es tan formal, tú tranquilo.","src":"voz039/c39Christiannombre3.ogg"},{"id":"c39Christiannombre4","text":"Gracias por decirme cómo te llamas, {n}. A partir de ahora te lo diré de vez en cuando, con cariño.","voz":"Gracias por decirme cómo te llamas, {n}. A partir de ahora te lo diré de vez en cuando, con cariño.","src":"voz039/c39Christiannombre4.ogg"},{"id":"c39Christiannombre5","text":"{n}, qué alegría. Hay nombres que le sientan bien a un plató, y el tuyo es uno.","voz":"{n}, qué alegría. Hay nombres que le sientan bien a un plató, y el tuyo es uno.","src":"voz039/c39Christiannombre5.ogg"},{"id":"c39Christiannombre6","text":"Anotado, {n}. Si otro día vuelves, sigo sabiendo quién eres, aquí en este teléfono.","voz":"Anotado, {n}. Si otro día vuelves, sigo sabiendo quién eres, aquí en este teléfono.","src":"voz039/c39Christiannombre6.ogg"},{"id":"c39Christiannombre7","text":"¡Hola, {n}! Ya era hora de ponernos nombre. El mío, en este juego, es Christian.","voz":"¡Hola, {n}! Ya era hora de ponernos nombre. El mío, en este juego, es Christian.","src":"voz039/c39Christiannombre7.ogg"}],"nombreIker":[{"id":"c39ChristiannombreIker0","text":"¡Iker! Qué alegría tenerte en el plató de Pasapalabra. Ya me acuerdo de tu nombre.","voz":"¡Iker! Qué alegría tenerte en el plató de Pasapalabra. Ya me acuerdo de tu nombre.","src":"voz039/c39ChristiannombreIker0.ogg"},{"id":"c39ChristiannombreIker1","text":"Iker, encantado de verdad. Este plató brilla más cuando estás tú al otro lado.","voz":"Iker, encantado de verdad. Este plató brilla más cuando estás tú al otro lado.","src":"voz039/c39ChristiannombreIker1.ogg"},{"id":"c39ChristiannombreIker2","text":"¡Me llamo Christian, y tú Iker! Qué bien suena eso. Pasa, que te estaba esperando.","voz":"¡Me llamo Christian, y tú Iker! Qué bien suena eso. Pasa, que te estaba esperando.","src":"voz039/c39ChristiannombreIker2.ogg"},{"id":"c39ChristiannombreIker3","text":"Iker, qué gusto. Me guardo tu nombre como si fuera una palabra preciosa del rosco.","voz":"Iker, qué gusto. Me guardo tu nombre como si fuera una palabra preciosa del rosco.","src":"voz039/c39ChristiannombreIker3.ogg"},{"id":"c39ChristiannombreIker4","text":"¡Iker! Ya no se me olvida. Dime qué te apetece: un rosco, un programa o una charla sin prisa.","voz":"¡Iker! Ya no se me olvida. Dime qué te apetece: un rosco, un programa o una charla sin prisa.","src":"voz039/c39ChristiannombreIker4.ogg"},{"id":"c39ChristiannombreIker5","text":"Qué ilusión, Iker. Gracias por presentarte. Aquí tienes tu sitio, de verdad.","voz":"Qué ilusión, Iker. Gracias por presentarte. Aquí tienes tu sitio, de verdad.","src":"voz039/c39ChristiannombreIker5.ogg"},{"id":"c39ChristiannombreIker6","text":"Iker, compañero de plató. Encantado. ¿Empezamos con una sonrisa y una letra?","voz":"Iker, compañero de plató. Encantado. ¿Empezamos con una sonrisa y una letra?","src":"voz039/c39ChristiannombreIker6.ogg"},{"id":"c39ChristiannombreIker7","text":"¡Iker! Me alegra un montón. A partir de ahora te llamaré por tu nombre, como se merece.","voz":"¡Iker! Me alegra un montón. A partir de ahora te llamaré por tu nombre, como se merece.","src":"voz039/c39ChristiannombreIker7.ogg"}],"corto":[{"id":"c39Christiancorto0","text":"Vale, me quedo con eso. ¿Seguimos con el rosco o prefieres que te cuente algo del programa?","voz":"Vale, me quedo con eso. ¿Seguimos con el rosco o prefieres que te cuente algo del programa?","src":"voz039/c39Christiancorto0.ogg"},{"id":"c39Christiancorto1","text":"De acuerdo. Estoy aquí, sin prisa. Dime tú el siguiente paso.","voz":"De acuerdo. Estoy aquí, sin prisa. Dime tú el siguiente paso.","src":"voz039/c39Christiancorto1.ogg"},{"id":"c39Christiancorto2","text":"Perfecto. A veces un «vale» vale más que un discurso. ¿Qué te apetece ahora?","voz":"Perfecto. A veces un «vale» vale más que un discurso. ¿Qué te apetece ahora?","src":"voz039/c39Christiancorto2.ogg"},{"id":"c39Christiancorto3","text":"Hecho. Si quieres, te propongo un chiste malo o una partida al rosco. Tú eliges.","voz":"Hecho. Si quieres, te propongo un chiste malo o una partida al rosco. Tú eliges.","src":"voz039/c39Christiancorto3.ogg"},{"id":"c39Christiancorto4","text":"Entendido. Sigo a tu ritmo. Cuando quieras, tiras de un tema y yo entro.","voz":"Entendido. Sigo a tu ritmo. Cuando quieras, tiras de un tema y yo entro.","src":"voz039/c39Christiancorto4.ogg"},{"id":"c39Christiancorto5","text":"Sí, vamos allá. ¿Una letra, una pregunta o seguimos charlando un poquito?","voz":"Sí, vamos allá. ¿Una letra, una pregunta o seguimos charlando un poquito?","src":"voz039/c39Christiancorto5.ogg"}],"fallback":[{"id":"c39Christianfallback0","text":"«{q}»… me has dejado con curiosidad. ¿Me lo cuentas un poco mejor? ¿Tiene que ver con el programa o con tu día?","voz":"Eso que has dicho me ha dejado con curiosidad. ¿Me lo cuentas un poco mejor? ¿Tiene que ver con el programa o con tu día?","src":"voz039/c39Christianfallback0.ogg"},{"id":"c39Christianfallback1","text":"Oye, lo de «{q}» me suena interesante. No quiero dejarlo pasar: cuéntame un poquito más.","voz":"Oye, eso me suena interesante. No quiero dejarlo pasar: cuéntame un poquito más.","src":"voz039/c39Christianfallback1.ogg"},{"id":"c39Christianfallback2","text":"Me has dicho «{q}» y me he quedado con la mosca detrás de la oreja. ¿Me lo explicas a tu manera?","voz":"Me has dejado con la mosca detrás de la oreja. ¿Me lo explicas a tu manera?","src":"voz039/c39Christianfallback2.ogg"},{"id":"c39Christianfallback3","text":"¡Anda, «{q}»! No me lo esperaba. ¿Es una afición, una duda o una broma? Me sirve cualquiera.","voz":"¡Anda! No me lo esperaba. ¿Es una afición, una duda o una broma? Me sirve cualquiera.","src":"voz039/c39Christianfallback3.ogg"},{"id":"c39Christianfallback4","text":"Sobre «{q}» te escucho con atención. Si quieres, lo ligamos luego a un rosco, pero ahora cuéntame.","voz":"Te escucho con atención. Si quieres, lo ligamos luego a un rosco, pero ahora cuéntame.","src":"voz039/c39Christianfallback4.ogg"},{"id":"c39Christianfallback5","text":"«{q}»… qué tema más bueno para un plató. ¿Me das un poco más de hilo, que me has enganchado?","voz":"Qué tema más bueno para un plató. ¿Me das un poco más de hilo, que me has enganchado?","src":"voz039/c39Christianfallback5.ogg"},{"id":"c39Christianfallback6","text":"No quiero salir del paso con una frase vaga: me interesa eso de «{q}». ¿Me lo detallas un poco?","voz":"No quiero salir del paso con una frase vaga: me interesa lo que has dicho. ¿Me lo detallas un poco?","src":"voz039/c39Christianfallback6.ogg"},{"id":"c39Christianfallback7","text":"Me has sacado de las letras un momentito, con eso de «{q}», y me parece estupendo. Sigue, te escucho.","voz":"Me has sacado de las letras un momentito, y me parece estupendo. Sigue, te escucho.","src":"voz039/c39Christianfallback7.ogg"},{"id":"c39Christianfallback8","text":"«{q}» merece una respuesta de verdad. Cuéntame qué te apetece hablar y yo me quedo.","voz":"Lo que has dicho merece una respuesta de verdad. Cuéntame qué te apetece hablar y yo me quedo.","src":"voz039/c39Christianfallback8.ogg"},{"id":"c39Christianfallback9","text":"Estoy aquí para eso, también para lo que no es el rosco. ¿Me lo explicas un poco más eso de «{q}»?","voz":"Estoy aquí para eso, también para lo que no es el rosco. ¿Me lo explicas un poco más?","src":"voz039/c39Christianfallback9.ogg"}]},"Lola":{"saludo":[{"id":"c39Lolasaludo0","text":"¡Hola, hola! Soy Lola y ya tenía ganas de que alguien escribiera. ¿Qué te apetece hoy?","voz":"¡Hola, hola! Soy Lola y ya tenía ganas de que alguien escribiera. ¿Qué te apetece hoy?","src":"voz039/c39Lolasaludo0.ogg"},{"id":"c39Lolasaludo1","text":"¡Ey! Qué ilusión, de verdad. Pasa, que este plató con gente se vuelve mucho más alegre.","voz":"¡Ey! Qué ilusión, de verdad. Pasa, que este plató con gente se vuelve mucho más alegre.","src":"voz039/c39Lolasaludo1.ogg"},{"id":"c39Lolasaludo2","text":"¡Buenas! Si vienes a charlar, has dado en el clavo. Yo soy de las que hablan y se ríen.","voz":"¡Buenas! Si vienes a charlar, has dado en el clavo. Yo soy de las que hablan y se ríen.","src":"voz039/c39Lolasaludo2.ogg"},{"id":"c39Lolasaludo3","text":"¡Hola! Yo voy de buen humor, avisé. ¿Tú vienes a jugar o a soltar una confidencia?","voz":"¡Hola! Yo voy de buen humor, avisé. ¿Tú vienes a jugar o a soltar una confidencia?","src":"voz039/c39Lolasaludo3.ogg"},{"id":"c39Lolasaludo4","text":"Muy buenas, cielo. Aquí Lola, a tu servicio, sin protocolo y con ganas de fiesta.","voz":"Muy buenas, cielo. Aquí Lola, a tu servicio, sin protocolo y con ganas de fiesta.","src":"voz039/c39Lolasaludo4.ogg"},{"id":"c39Lolasaludo5","text":"¡Hola! Qué bien que estés. Si te sientas un segundo, ya somos dos para el cotilleo sano del rosco.","voz":"¡Hola! Qué bien que estés. Si te sientas un segundo, ya somos dos para el cotilleo sano del rosco.","src":"voz039/c39Lolasaludo5.ogg"},{"id":"c39Lolasaludo6","text":"Hey, bienvenido. Yo soy un poco cotorra, lo admito, pero con buen corazón. ¿Qué tal?","voz":"Hey, bienvenido. Yo soy un poco cotorra, lo admito, pero con buen corazón. ¿Qué tal?","src":"voz039/c39Lolasaludo6.ogg"},{"id":"c39Lolasaludo7","text":"¡Hola! Hoy tengo el día hablador. Tú dime una palabra y yo te sigo el rollo.","voz":"¡Hola! Hoy tengo el día hablador. Tú dime una palabra y yo te sigo el rollo.","src":"voz039/c39Lolasaludo7.ogg"}],"saludoIker":[{"id":"c39LolasaludoIker0","text":"¡Iker, hola! Qué alegría que hayas vuelto. Cuéntame, ¿hoy de rosco o de charla?","voz":"¡Iker, hola! Qué alegría que hayas vuelto. Cuéntame, ¿hoy de rosco o de charla?","src":"voz039/c39LolasaludoIker0.ogg"},{"id":"c39LolasaludoIker1","text":"Iker, ey, pasa. El plató ya te espera con una sonrisa. ¿Qué te apetece?","voz":"Iker, ey, pasa. El plató ya te espera con una sonrisa. ¿Qué te apetece?","src":"voz039/c39LolasaludoIker1.ogg"},{"id":"c39LolasaludoIker2","text":"¡Hola, Iker! Me alegro un montón. Dime tú, que yo ya estaba cotorreando sola.","voz":"¡Hola, Iker! Me alegro un montón. Dime tú, que yo ya estaba cotorreando sola.","src":"voz039/c39LolasaludoIker2.ogg"},{"id":"c39LolasaludoIker3","text":"Iker, bienvenido otra vez. Hoy también hay sitio y ganas. ¿Por dónde empezamos?","voz":"Iker, bienvenido otra vez. Hoy también hay sitio y ganas. ¿Por dónde empezamos?","src":"voz039/c39LolasaludoIker3.ogg"},{"id":"c39LolasaludoIker4","text":"¡Iker! Qué gusto verte. ¿Jugamos, hablamos, o las dos cosas, que es lo mío?","voz":"¡Iker! Qué gusto verte. ¿Jugamos, hablamos, o las dos cosas, que es lo mío?","src":"voz039/c39LolasaludoIker4.ogg"}],"comoestas":[{"id":"c39Lolacomoestas0","text":"¡Yo fenomenal, oye! Como si me hubiera puesto verde una zeta. ¿Y tú, cómo estás?","voz":"¡Yo fenomenal, oye! Como si me hubiera puesto verde una zeta. ¿Y tú, cómo estás?","src":"voz039/c39Lolacomoestas0.ogg"},{"id":"c39Lolacomoestas1","text":"Estoy de un humor de monada. ¿Tú cómo te encuentras, de verdad?","voz":"Estoy de un humor de monada. ¿Tú cómo te encuentras, de verdad?","src":"voz039/c39Lolacomoestas1.ogg"},{"id":"c39Lolacomoestas2","text":"Yo muy bien, gracias por preguntar, que no todo el mundo lo hace. ¿Tú qué tal el día?","voz":"Yo muy bien, gracias por preguntar, que no todo el mundo lo hace. ¿Tú qué tal el día?","src":"voz039/c39Lolacomoestas2.ogg"},{"id":"c39Lolacomoestas3","text":"Contenta, nerviosa de gusto, como antes de un rosco. ¿Tú cómo vas?","voz":"Contenta, nerviosa de gusto, como antes de un rosco. ¿Tú cómo vas?","src":"voz039/c39Lolacomoestas3.ogg"},{"id":"c39Lolacomoestas4","text":"De lujo. Si tú no tanto, me quedo aquí y te saco una sonrisa, a ver si cuela.","voz":"De lujo. Si tú no tanto, me quedo aquí y te saco una sonrisa, a ver si cuela.","src":"voz039/c39Lolacomoestas4.ogg"},{"id":"c39Lolacomoestas5","text":"Yo estupenda. Pregúntame lo que quieras, pero primero dime cómo estás tú, que me importa.","voz":"Yo estupenda. Pregúntame lo que quieras, pero primero dime cómo estás tú, que me importa.","src":"voz039/c39Lolacomoestas5.ogg"},{"id":"c39Lolacomoestas6","text":"Voy que chuto, sí. ¿Tú vienes con energía o te pongo yo un poco de ambientillo?","voz":"Voy que chuto, sí. ¿Tú vienes con energía o te pongo yo un poco de ambientillo?","src":"voz039/c39Lolacomoestas6.ogg"},{"id":"c39Lolacomoestas7","text":"Genial. Un «qué tal» de los buenos se responde con sinceridad: yo bien, ¿y tú?","voz":"Genial. Un «qué tal» de los buenos se responde con sinceridad: yo bien, ¿y tú?","src":"voz039/c39Lolacomoestas7.ogg"}],"animo":[{"id":"c39Lolaanimo0","text":"Ay, si estás regular, ven aquí. No hace falta que estés brillante. Te acompaño y ya está.","voz":"Ay, si estás regular, ven aquí. No hace falta que estés brillante. Te acompaño y ya está.","src":"voz039/c39Lolaanimo0.ogg"},{"id":"c39Lolaanimo1","text":"Ánimo, de verdad. Los días grises también merecen un plató amable y una amiga parlanchina.","voz":"Ánimo, de verdad. Los días grises también merecen un plató amable y una amiga parlanchina.","src":"voz039/c39Lolaanimo1.ogg"},{"id":"c39Lolaanimo2","text":"Si estás cansado o triste, lo entiendo. Yo no te doy un sermón, te doy compañía.","voz":"Si estás cansado o triste, lo entiendo. Yo no te doy un sermón, te doy compañía.","src":"voz039/c39Lolaanimo2.ogg"},{"id":"c39Lolaanimo3","text":"Vamos a ir despacito. Una frase, una letra, un respiro. No estás solo en esto.","voz":"Vamos a ir despacito. Una frase, una letra, un respiro. No estás solo en esto.","src":"voz039/c39Lolaanimo3.ogg"},{"id":"c39Lolaanimo4","text":"Hoy puede pesar todo un poco. Yo me quedo, aunque solo sea para que no se haga tan largo.","voz":"Hoy puede pesar todo un poco. Yo me quedo, aunque solo sea para que no se haga tan largo.","src":"voz039/c39Lolaanimo4.ogg"},{"id":"c39Lolaanimo5","text":"Si te da rabia no acertar, te abrazo en diferido y seguimos. Nadie se juega la vida en una letra.","voz":"Si te da rabia no acertar, te abrazo en diferido y seguimos. Nadie se juega la vida en una letra.","src":"voz039/c39Lolaanimo5.ogg"},{"id":"c39Lolaanimo6","text":"Ánimo. Aquí no hay prisa ni nota final. Tú relájate un poquito, si puedes.","voz":"Ánimo. Aquí no hay prisa ni nota final. Tú relájate un poquito, si puedes.","src":"voz039/c39Lolaanimo6.ogg"},{"id":"c39Lolaanimo7","text":"Cuando uno está bajo, un chiste malo o un «estoy aquí» ayudan. Tienes las dos cosas.","voz":"Cuando uno está bajo, un chiste malo o un «estoy aquí» ayudan. Tienes las dos cosas.","src":"voz039/c39Lolaanimo7.ogg"}],"chiste":[{"id":"c39Lolachiste0","text":"Va, una tonta: ¿qué le dice el reloj al rosco? «Tú sigue, que yo ya voy fatal de tiempo.»","voz":"Va, una tonta: ¿qué le dice el reloj al rosco? «Tú sigue, que yo ya voy fatal de tiempo.»","src":"voz039/c39Lolachiste0.ogg"},{"id":"c39Lolachiste1","text":"¿Cuál es la letra más cotilla? La uve, porque siempre pregunta «ves, ves». Vale, es un poco chufa.","voz":"¿Cuál es la letra más cotilla? La uve, porque siempre pregunta «ves, ves». Vale, es un poco chufa.","src":"voz039/c39Lolachiste1.ogg"},{"id":"c39Lolachiste2","text":"Te suelto una: el bote y yo tenemos en común que nos ponemos nerviosos si nos nombran mucho.","voz":"Te suelto una: el bote y yo tenemos en común que nos ponemos nerviosos si nos nombran mucho.","src":"voz039/c39Lolachiste2.ogg"},{"id":"c39Lolachiste3","text":"¿Por qué Lola no se pierde en el plató? Porque siempre encuentra la clave. ¡Bueno, perdona!","voz":"¿Por qué Lola no se pierde en el plató? Porque siempre encuentra la clave. ¡Bueno, perdona!","src":"voz039/c39Lolachiste3.ogg"},{"id":"c39Lolachiste4","text":"Una rápida: la eñe entra a un bar y pide… nada, que está de dieta. Ay, lo siento.","voz":"Una rápida: la eñe entra a un bar y pide… nada, que está de dieta. Ay, lo siento.","src":"voz039/c39Lolachiste4.ogg"},{"id":"c39Lolachiste5","text":"¿Qué hace una palabra cuando se pone tímida? Pasapalabra y se esconde en la siguiente vuelta.","voz":"¿Qué hace una palabra cuando se pone tímida? Pasapalabra y se esconde en la siguiente vuelta.","src":"voz039/c39Lolachiste5.ogg"},{"id":"c39Lolachiste6","text":"Mi humor es casero, como una tortilla un poco viva. Si no ríes, al menos has soplado.","voz":"Mi humor es casero, como una tortilla un poco viva. Si no ríes, al menos has soplado.","src":"voz039/c39Lolachiste6.ogg"},{"id":"c39Lolachiste7","text":"Oye, ¿sabes por qué la jota es tan valiente? Porque se lanza sin red. Vale, me voy a callar un poco.","voz":"Oye, ¿sabes por qué la jota es tan valiente? Porque se lanza sin red. Vale, me voy a callar un poco.","src":"voz039/c39Lolachiste7.ogg"}],"favoritos":[{"id":"c39Lolafavoritos0","text":"A mí me flipan las sintonías y las palmas del público. ¿Tú qué es lo que más te gusta?","voz":"A mí me flipan las sintonías y las palmas del público. ¿Tú qué es lo que más te gusta?","src":"voz039/c39Lolafavoritos0.ogg"},{"id":"c39Lolafavoritos1","text":"Mi favorito es cuando alguien se ríe en el chat. ¿Y el tuyo, del programa o de la vida?","voz":"Mi favorito es cuando alguien se ríe en el chat. ¿Y el tuyo, del programa o de la vida?","src":"voz039/c39Lolafavoritos1.ogg"},{"id":"c39Lolafavoritos2","text":"De colores, el verde de acertar. De comida, lo que pinche un poco. ¿Tú qué prefieres?","voz":"De colores, el verde de acertar. De comida, lo que pinche un poco. ¿Tú qué prefieres?","src":"voz039/c39Lolafavoritos2.ogg"},{"id":"c39Lolafavoritos3","text":"Pregúntame por favoritos y me alargo, aviso. Empieza tú, que me interesa más lo tuyo.","voz":"Pregúntame por favoritos y me alargo, aviso. Empieza tú, que me interesa más lo tuyo.","src":"voz039/c39Lolafavoritos3.ogg"},{"id":"c39Lolafavoritos4","text":"Me encanta un buen cotilleo de letras: palabras raras, recuerdos, definiciones. ¿Tú qué coleccionas?","voz":"Me encanta un buen cotilleo de letras: palabras raras, recuerdos, definiciones. ¿Tú qué coleccionas?","src":"voz039/c39Lolafavoritos4.ogg"},{"id":"c39Lolafavoritos5","text":"Mi momento favorito es el silencio justo antes de una letra difícil. ¿A ti qué te llega más?","voz":"Mi momento favorito es el silencio justo antes de una letra difícil. ¿A ti qué te llega más?","src":"voz039/c39Lolafavoritos5.ogg"},{"id":"c39Lolafavoritos6","text":"Si hablo de preferencias, me quedo con la gente espontánea. Como tú, si me dejas decirlo.","voz":"Si hablo de preferencias, me quedo con la gente espontánea. Como tú, si me dejas decirlo.","src":"voz039/c39Lolafavoritos6.ogg"},{"id":"c39Lolafavoritos7","text":"¿Comida, color, prueba, letra? Elige tema, que yo tengo opinión para un rato.","voz":"¿Comida, color, prueba, letra? Elige tema, que yo tengo opinión para un rato.","src":"voz039/c39Lolafavoritos7.ogg"}],"presentadores":[{"id":"c39Lolapresentadores0","text":"Christian es el anfitrión de este chat, y yo soy Lola, un personaje inventado. Puedes hablar con los dos.","voz":"Christian es el anfitrión de este chat, y yo soy Lola, un personaje inventado. Puedes hablar con los dos.","src":"voz039/c39Lolapresentadores0.ogg"},{"id":"c39Lolapresentadores1","text":"Yo no soy presentadora de la tele, soy de este juego. Pero te recibo con la misma ilusión.","voz":"Yo no soy presentadora de la tele, soy de este juego. Pero te recibo con la misma ilusión.","src":"voz039/c39Lolapresentadores1.ogg"},{"id":"c39Lolapresentadores2","text":"Si te cae bien Christian, a mí también. Y si quieres otro rollo, aquí estoy yo, más de broma.","voz":"Si te cae bien Christian, a mí también. Y si quieres otro rollo, aquí estoy yo, más de broma.","src":"voz039/c39Lolapresentadores2.ogg"},{"id":"c39Lolapresentadores3","text":"Los presentadores de verdad han hecho grande este programa. Yo solo acompaño, con respeto y alegría.","voz":"Los presentadores de verdad han hecho grande este programa. Yo solo acompaño, con respeto y alegría.","src":"voz039/c39Lolapresentadores3.ogg"},{"id":"c39Lolapresentadores4","text":"Javi es más de chascarrillo, Pablo más tranquilo, yo más cotorra. Elige según el día.","voz":"Javi es más de chascarrillo, Pablo más tranquilo, yo más cotorra. Elige según el día.","src":"voz039/c39Lolapresentadores4.ogg"},{"id":"c39Lolapresentadores5","text":"Presentar, para mí, es hacer que la otra persona se sienta a gusto. Eso intento.","voz":"Presentar, para mí, es hacer que la otra persona se sienta a gusto. Eso intento.","src":"voz039/c39Lolapresentadores5.ogg"},{"id":"c39Lolapresentadores6","text":"Si alguna vez oyes «Lola, inventada», es verdad: soy un personaje. Pero la simpatía es sincera.","voz":"Si alguna vez oyes «Lola, inventada», es verdad: soy un personaje. Pero la simpatía es sincera.","src":"voz039/c39Lolapresentadores6.ogg"},{"id":"c39Lolapresentadores7","text":"A mí me gusta cuando el presentador deja hablar. Así que dime, que yo también sé callar… a ratos.","voz":"A mí me gusta cuando el presentador deja hablar. Así que dime, que yo también sé callar… a ratos.","src":"voz039/c39Lolapresentadores7.ogg"}],"programa":[{"id":"c39Lolaprograma0","text":"Pasapalabra es mi debilidad: letras, público y esa emoción tonta y bonita de acertar.","voz":"Pasapalabra es mi debilidad: letras, público y esa emoción tonta y bonita de acertar.","src":"voz039/c39Lolaprograma0.ogg"},{"id":"c39Lolaprograma1","text":"Este programa une a la familia delante de la tele. Aquí intentamos que pase un poco lo mismo.","voz":"Este programa une a la familia delante de la tele. Aquí intentamos que pase un poco lo mismo.","src":"voz039/c39Lolaprograma1.ogg"},{"id":"c39Lolaprograma2","text":"Me encanta que puedas ver programas y además charlar. Es como el descanso de la publicidad, pero más amable.","voz":"Me encanta que puedas ver programas y además charlar. Es como el descanso de la publicidad, pero más amable.","src":"voz039/c39Lolaprograma2.ogg"},{"id":"c39Lolaprograma3","text":"Si lo ves desde hace años, te entiendo: entra y ya no se sale. ¿Tú de qué etapa eres más?","voz":"Si lo ves desde hace años, te entiendo: entra y ya no se sale. ¿Tú de qué etapa eres más?","src":"voz039/c39Lolaprograma3.ogg"},{"id":"c39Lolaprograma4","text":"El concurso es un clásico y este juego lo trata con cariño. Nada de cargárselo, solo acompañarlo.","voz":"El concurso es un clásico y este juego lo trata con cariño. Nada de cargárselo, solo acompañarlo.","src":"voz039/c39Lolaprograma4.ogg"},{"id":"c39Lolaprograma5","text":"A mí me gusta cuando un programa se ve entero, sin prisa. Si te animas, te hago de compañía.","voz":"A mí me gusta cuando un programa se ve entero, sin prisa. Si te animas, te hago de compañía.","src":"voz039/c39Lolaprograma5.ogg"},{"id":"c39Lolaprograma6","text":"Hay quien viene por el bote y quien viene por la sintonía. Los dos tienen razón.","voz":"Hay quien viene por el bote y quien viene por la sintonía. Los dos tienen razón.","src":"voz039/c39Lolaprograma6.ogg"},{"id":"c39Lolaprograma7","text":"Pasapalabra, para mí, es hospitalidad con letras. Pasa y cuéntame qué te gusta de él.","voz":"Pasapalabra, para mí, es hospitalidad con letras. Pasa y cuéntame qué te gusta de él.","src":"voz039/c39Lolaprograma7.ogg"}],"rosco":[{"id":"c39Lolarosco0","text":"El rosco es mi debilidad, no te voy a mentir. ¿Echamos una partida o primero lo comentamos?","voz":"El rosco es mi debilidad, no te voy a mentir. ¿Echamos una partida o primero lo comentamos?","src":"voz039/c39Lolarosco0.ogg"},{"id":"c39Lolarosco1","text":"Si una letra se te atraganta, pasapalabra y viva la vida. Luego vuelve y a lo mejor sale sola.","voz":"Si una letra se te atraganta, pasapalabra y viva la vida. Luego vuelve y a lo mejor sale sola.","src":"voz039/c39Lolarosco1.ogg"},{"id":"c39Lolarosco2","text":"Los aciertos se ponen verdes y da una alegría tonta. Yo celebro hasta las de la uve.","voz":"Los aciertos se ponen verdes y da una alegría tonta. Yo celebro hasta las de la uve.","src":"voz039/c39Lolarosco2.ogg"},{"id":"c39Lolarosco3","text":"Podéis jugar de uno a cuatro en el mismo teléfono. Ideal para reírse en el sofá.","voz":"Podéis jugar de uno a cuatro en el mismo teléfono. Ideal para reírse en el sofá.","src":"voz039/c39Lolarosco3.ogg"},{"id":"c39Lolarosco4","text":"Hay letras que dan respeto, sí. Por eso está bien pasar y volver con más aire.","voz":"Hay letras que dan respeto, sí. Por eso está bien pasar y volver con más aire.","src":"voz039/c39Lolarosco4.ogg"},{"id":"c39Lolarosco5","text":"Yo en un rosco sería de las que se lanzan y luego se arrepienten, oye. ¿Tú eres más de pensártelo?","voz":"Yo en un rosco sería de las que se lanzan y luego se arrepienten, oye. ¿Tú eres más de pensártelo?","src":"voz039/c39Lolarosco5.ogg"},{"id":"c39Lolarosco6","text":"Si quieres, te recuerdo las reglas en dos frases: definición, letra, aciertas o pasas. El reloj hace el resto.","voz":"Si quieres, te recuerdo las reglas en dos frases: definición, letra, aciertas o pasas. El reloj hace el resto.","src":"voz039/c39Lolarosco6.ogg"},{"id":"c39Lolarosco7","text":"Un rosco no es un examen. Es un juego. Si te lo tomas así, sale hasta mejor.","voz":"Un rosco no es un examen. Es un juego. Si te lo tomas así, sale hasta mejor.","src":"voz039/c39Lolarosco7.ogg"}],"prueba":[{"id":"c39Lolaprueba0","text":"Las pruebas están en su menú, con vídeo completo. Escalera, Pulsador y compañía, todas juntas.","voz":"Las pruebas están en su menú, con vídeo completo. Escalera, Pulsador y compañía, todas juntas.","src":"voz039/c39Lolaprueba0.ogg"},{"id":"c39Lolaprueba1","text":"A mí las pruebas de equipo me ponen de un nervio rico. ¿Tú con cuál sufres más, de gusto?","voz":"A mí las pruebas de equipo me ponen de un nervio rico. ¿Tú con cuál sufres más, de gusto?","src":"voz039/c39Lolaprueba1.ogg"},{"id":"c39Lolaprueba2","text":"Si quieres revivir un momento, entra en Las pruebas y lo repites las veces que te dé la gana.","voz":"Si quieres revivir un momento, entra en Las pruebas y lo repites las veces que te dé la gana.","src":"voz039/c39Lolaprueba2.ogg"},{"id":"c39Lolaprueba3","text":"Donde Están, el Coco, las Cruzadas… hay un rato de sonrisa y de «no puede ser».","voz":"Donde Están, el Coco, las Cruzadas… hay un rato de sonrisa y de «no puede ser».","src":"voz039/c39Lolaprueba3.ogg"},{"id":"c39Lolaprueba4","text":"Te oriento: menú de pruebas, eliges la que te apetezca y a verla. Si te atascas, me llamas.","voz":"Te oriento: menú de pruebas, eliges la que te apetezca y a verla. Si te atascas, me llamas.","src":"voz039/c39Lolaprueba4.ogg"},{"id":"c39Lolaprueba5","text":"Las pruebas y el rosco son primos: misma casa, distinto jaleo. ¿Cuál te apetece hoy?","voz":"Las pruebas y el rosco son primos: misma casa, distinto jaleo. ¿Cuál te apetece hoy?","src":"voz039/c39Lolaprueba5.ogg"},{"id":"c39Lolaprueba6","text":"Ver una prueba con alguien comentando es más divertido. Por eso estoy aquí, un poco cotilla.","voz":"Ver una prueba con alguien comentando es más divertido. Por eso estoy aquí, un poco cotilla.","src":"voz039/c39Lolaprueba6.ogg"},{"id":"c39Lolaprueba7","text":"Si una prueba se te dio mal en su día, ahora puedes verla en paz. Tiene su punto.","voz":"Si una prueba se te dio mal en su día, ahora puedes verla en paz. Tiene su punto.","src":"voz039/c39Lolaprueba7.ogg"}],"musica":[{"id":"c39Lolamusica0","text":"La sintonía me pone la piel de gallina, lo admito. Es de las que te entran para siempre.","voz":"La sintonía me pone la piel de gallina, lo admito. Es de las que te entran para siempre.","src":"voz039/c39Lolamusica0.ogg"},{"id":"c39Lolamusica1","text":"La música de los vídeos es la de verdad. Mi voz es sintética, Piper en español, de este juego.","voz":"La música de los vídeos es la de verdad. Mi voz es sintética, Piper en español, de este juego.","src":"voz039/c39Lolamusica1.ogg"},{"id":"c39Lolamusica2","text":"Si hablo alto, bajo un poco el vídeo. Y si te estorbo, me silencias, sin enfado.","voz":"Si hablo alto, bajo un poco el vídeo. Y si te estorbo, me silencias, sin enfado.","src":"voz039/c39Lolamusica2.ogg"},{"id":"c39Lolamusica3","text":"A mí dame una cabecera y ya estoy bailando en la silla. ¿Tú también o eres más serio?","voz":"A mí dame una cabecera y ya estoy bailando en la silla. ¿Tú también o eres más serio?","src":"voz039/c39Lolamusica3.ogg"},{"id":"c39Lolamusica4","text":"Hay canciones que te traen el salón de casa. Esta sintonía es una de ellas, ¿a que sí?","voz":"Hay canciones que te traen el salón de casa. Esta sintonía es una de ellas, ¿a que sí?","src":"voz039/c39Lolamusica4.ogg"},{"id":"c39Lolamusica5","text":"Si quieres dejar que suene el programa, yo me callo un rato. Si quieres charla, también.","voz":"Si quieres dejar que suene el programa, yo me callo un rato. Si quieres charla, también.","src":"voz039/c39Lolamusica5.ogg"},{"id":"c39Lolamusica6","text":"El oído y las palabras se llevan bien. Por eso este concurso es tan bonito.","voz":"El oído y las palabras se llevan bien. Por eso este concurso es tan bonito.","src":"voz039/c39Lolamusica6.ogg"},{"id":"c39Lolamusica7","text":"No canto en directo, que te libras, pero te acompaño en el estribillo imaginario.","voz":"No canto en directo, que te libras, pero te acompaño en el estribillo imaginario.","src":"voz039/c39Lolamusica7.ogg"}],"video":[{"id":"c39Lolavideo0","text":"Los programas se ven en la pantalla del plató si tienes la Biblioteca instalada.","voz":"Los programas se ven en la pantalla del plató si tienes la Biblioteca instalada.","src":"voz039/c39Lolavideo0.ogg"},{"id":"c39Lolavideo1","text":"Mis comentarios sobre el vídeo son inventados, para hacer compañía. El programa no se recorta.","voz":"Mis comentarios sobre el vídeo son inventados, para hacer compañía. El programa no se recorta.","src":"voz039/c39Lolavideo1.ogg"},{"id":"c39Lolavideo2","text":"Si un vídeo no abre, mira la Biblioteca. El chat, eso sí, no se va a ningún sitio.","voz":"Si un vídeo no abre, mira la Biblioteca. El chat, eso sí, no se va a ningún sitio.","src":"voz039/c39Lolavideo2.ogg"},{"id":"c39Lolavideo3","text":"¿Nochevieja, un día entre semana, Reyes? Dime y te animo a buscarlo en el menú.","voz":"¿Nochevieja, un día entre semana, Reyes? Dime y te animo a buscarlo en el menú.","src":"voz039/c39Lolavideo3.ogg"},{"id":"c39Lolavideo4","text":"Ver un programa entero es un planazo. Yo hago de amiga en el sofá de al lado.","voz":"Ver un programa entero es un planazo. Yo hago de amiga en el sofá de al lado.","src":"voz039/c39Lolavideo4.ogg"},{"id":"c39Lolavideo5","text":"En el menú de Telecinco está la lista. Si no sabes cuál, dime una pista y te ayudo.","voz":"En el menú de Telecinco está la lista. Si no sabes cuál, dime una pista y te ayudo.","src":"voz039/c39Lolavideo5.ogg"},{"id":"c39Lolavideo6","text":"Puedes pausar, hablar conmigo y seguir. No hay norma de silencio en la sala.","voz":"Puedes pausar, hablar conmigo y seguir. No hay norma de silencio en la sala.","src":"voz039/c39Lolavideo6.ogg"},{"id":"c39Lolavideo7","text":"La biblioteca es el armario de los recuerdos. Ábrelo cuando quieras.","voz":"La biblioteca es el armario de los recuerdos. Ábrelo cuando quieras.","src":"voz039/c39Lolavideo7.ogg"}],"juego":[{"id":"c39Lolajuego0","text":"Se puede ver, se puede jugar y se puede hablar. Tú eliges el mix.","voz":"Se puede ver, se puede jugar y se puede hablar. Tú eliges el mix.","src":"voz039/c39Lolajuego0.ogg"},{"id":"c39Lolajuego1","text":"El rosco por turnos es genial en casa. Un teléfono, varios valientes, muchas risas.","voz":"El rosco por turnos es genial en casa. Un teléfono, varios valientes, muchas risas.","src":"voz039/c39Lolajuego1.ogg"},{"id":"c39Lolajuego2","text":"Si te pierdes en el menú, pregúntame. Yo te dejo una ruta fácil, sin líos.","voz":"Si te pierdes en el menú, pregúntame. Yo te dejo una ruta fácil, sin líos.","src":"voz039/c39Lolajuego2.ogg"},{"id":"c39Lolajuego3","text":"Todo esto va en local, sin internet para el chat ni para el rosco. Cómodo, ¿verdad?","voz":"Todo esto va en local, sin internet para el chat ni para el rosco. Cómodo, ¿verdad?","src":"voz039/c39Lolajuego3.ogg"},{"id":"c39Lolajuego4","text":"Plan Lola: un saludo, una risa y una partida. Si te encaja, empezamos cuando digas.","voz":"Plan Lola: un saludo, una risa y una partida. Si te encaja, empezamos cuando digas.","src":"voz039/c39Lolajuego4.ogg"},{"id":"c39Lolajuego5","text":"Jugar solo también mola. No hace falta un público real, aunque yo aplauso imaginario sí doy.","voz":"Jugar solo también mola. No hace falta un público real, aunque yo aplauso imaginario sí doy.","src":"voz039/c39Lolajuego5.ogg"},{"id":"c39Lolajuego6","text":"Las reglas están para ayudar, no para marear. Si quieres, te las cuento a mi manera.","voz":"Las reglas están para ayudar, no para marear. Si quieres, te las cuento a mi manera.","src":"voz039/c39Lolajuego6.ogg"},{"id":"c39Lolajuego7","text":"Lo importante es que te lo pases bien. Lo demás, letras y tiempo, ya se da.","voz":"Lo importante es que te lo pases bien. Lo demás, letras y tiempo, ya se da.","src":"voz039/c39Lolajuego7.ogg"}],"quien":[{"id":"c39Lolaquien0","text":"Soy Lola, un personaje inventado de este juego. No soy una persona real, y por eso lo marco.","voz":"Soy Lola, un personaje inventado de este juego. No soy una persona real, y por eso lo marco.","src":"voz039/c39Lolaquien0.ogg"},{"id":"c39Lolaquien1","text":"No hay una inteligencia de internet detrás. Hay frases hechas con ganas y una voz Piper en español.","voz":"No hay una inteligencia de internet detrás. Hay frases hechas con ganas y una voz Piper en español.","src":"voz039/c39Lolaquien1.ogg"},{"id":"c39Lolaquien2","text":"Preguntar quién soy me parece de lo más normal. Soy tu compañera de plató, un poco cotorra, local y de buen rollo.","voz":"Preguntar quién soy me parece de lo más normal. Soy tu compañera de plató, un poco cotorra, local y de buen rollo.","src":"voz039/c39Lolaquien2.ogg"},{"id":"c39Lolaquien3","text":"Puedes hablar también con Christian, Javi o Pablo. Cada uno tiene su tono, todos inventados aquí.","voz":"Puedes hablar también con Christian, Javi o Pablo. Cada uno tiene su tono, todos inventados aquí.","src":"voz039/c39Lolaquien3.ogg"},{"id":"c39Lolaquien4","text":"No adivino cosas ni busco en la red. Te escucho y te contesto, aquí, en tu teléfono.","voz":"No adivino cosas ni busco en la red. Te escucho y te contesto, aquí, en tu teléfono.","src":"voz039/c39Lolaquien4.ogg"},{"id":"c39Lolaquien5","text":"Si sueno demasiado pizpireta, ya me conoces: soy Lola. Puedes pedirme calma, lo intento.","voz":"Si sueno demasiado pizpireta, ya me conoces: soy Lola. Puedes pedirme calma, lo intento.","src":"voz039/c39Lolaquien5.ogg"},{"id":"c39Lolaquien6","text":"Soy un avatar. La simpatía es de verdad; la biografía, inventada. Así de claro.","voz":"Soy un avatar. La simpatía es de verdad; la biografía, inventada. Así de claro.","src":"voz039/c39Lolaquien6.ogg"},{"id":"c39Lolaquien7","text":"Este chat es para acompañarte, no para sustituir a nadie de la tele. Yo estoy a tu lado, punto.","voz":"Este chat es para acompañarte, no para sustituir a nadie de la tele. Yo estoy a tu lado, punto.","src":"voz039/c39Lolaquien7.ogg"}],"elogio":[{"id":"c39Lolaelogio0","text":"¡Ay, qué monada! Me has puesto colorada, y eso que soy un personaje. Gracias, de corazón.","voz":"¡Ay, qué monada! Me has puesto colorada, y eso que soy un personaje. Gracias, de corazón.","src":"voz039/c39Lolaelogio0.ogg"},{"id":"c39Lolaelogio1","text":"Vaya cumplido. Me lo pongo de broche, oye. Tú también estás siendo un encanto.","voz":"Vaya cumplido. Me lo pongo de broche, oye. Tú también estás siendo un encanto.","src":"voz039/c39Lolaelogio1.ogg"},{"id":"c39Lolaelogio2","text":"Gracias, gracias. Un halago así me dura lo que un rosco bien dado: un rato largo.","voz":"Gracias, gracias. Un halago así me dura lo que un rosco bien dado: un rato largo.","src":"voz039/c39Lolaelogio2.ogg"},{"id":"c39Lolaelogio3","text":"Qué rico lo que has dicho. Este plató se merece gente como tú.","voz":"Qué rico lo que has dicho. Este plató se merece gente como tú.","src":"voz039/c39Lolaelogio3.ogg"},{"id":"c39Lolaelogio4","text":"Me has alegrado el momento, de verdad. Un aplauso imaginario para ti.","voz":"Me has alegrado el momento, de verdad. Un aplauso imaginario para ti.","src":"voz039/c39Lolaelogio4.ogg"},{"id":"c39Lolaelogio5","text":"Eres un sol. Y no lo digo por salir del paso, lo digo porque se nota.","voz":"Eres un sol. Y no lo digo por salir del paso, lo digo porque se nota.","src":"voz039/c39Lolaelogio5.ogg"},{"id":"c39Lolaelogio6","text":"Con mensajes así, yo firmo para quedarme en el plató un rato más.","voz":"Con mensajes así, yo firmo para quedarme en el plató un rato más.","src":"voz039/c39Lolaelogio6.ogg"},{"id":"c39Lolaelogio7","text":"¡Toma ya! Qué bien sienta. Gracias por el cariño.","voz":"¡Toma ya! Qué bien sienta. Gracias por el cariño.","src":"voz039/c39Lolaelogio7.ogg"}],"gracias":[{"id":"c39Lolagracias0","text":"¡A ti! Por escribir, por reírte y por estar. De nada no, de mucho.","voz":"¡A ti! Por escribir, por reírte y por estar. De nada no, de mucho.","src":"voz039/c39Lolagracias0.ogg"},{"id":"c39Lolagracias1","text":"No hay de qué, de verdad. Para esto estoy, y me encanta.","voz":"No hay de qué, de verdad. Para esto estoy, y me encanta.","src":"voz039/c39Lolagracias1.ogg"},{"id":"c39Lolagracias2","text":"El gracias es mutuo, oye. Tú pones la visita y yo pongo la cotorra.","voz":"El gracias es mutuo, oye. Tú pones la visita y yo pongo la cotorra.","src":"voz039/c39Lolagracias2.ogg"},{"id":"c39Lolagracias3","text":"Un gracias me deja mimosa. Seguimos cuando tú quieras.","voz":"Un gracias me deja mimosa. Seguimos cuando tú quieras.","src":"voz039/c39Lolagracias3.ogg"},{"id":"c39Lolagracias4","text":"Gracias a ti, que eres quien hace que esto tenga gracia.","voz":"Gracias a ti, que eres quien hace que esto tenga gracia.","src":"voz039/c39Lolagracias4.ogg"},{"id":"c39Lolagracias5","text":"Para ti, siempre. Si sale otra cosa, me llamas y ya estoy.","voz":"Para ti, siempre. Si sale otra cosa, me llamas y ya estoy.","src":"voz039/c39Lolagracias5.ogg"},{"id":"c39Lolagracias6","text":"De nada, cielo. La puerta del plató sigue abierta.","voz":"De nada, cielo. La puerta del plató sigue abierta.","src":"voz039/c39Lolagracias6.ogg"},{"id":"c39Lolagracias7","text":"Se agradece, se agradece. Qué gusto da la educación y el cariño.","voz":"Se agradece, se agradece. Qué gusto da la educación y el cariño.","src":"voz039/c39Lolagracias7.ogg"}],"despedida":[{"id":"c39Loladespedida0","text":"¡Hasta luego! Vuelve, que yo sigo aquí con las ganas de charla.","voz":"¡Hasta luego! Vuelve, que yo sigo aquí con las ganas de charla.","src":"voz039/c39Loladespedida0.ogg"},{"id":"c39Loladespedida1","text":"Nos vemos, de verdad. Que te vaya genial ahí fuera.","voz":"Nos vemos, de verdad. Que te vaya genial ahí fuera.","src":"voz039/c39Loladespedida1.ogg"},{"id":"c39Loladespedida2","text":"Adiós, pero de los que saben que habrá un hola después.","voz":"Adiós, pero de los que saben que habrá un hola después.","src":"voz039/c39Loladespedida2.ogg"},{"id":"c39Loladespedida3","text":"Chao, chao. Te dejo un hueco en el sofá imaginario.","voz":"Chao, chao. Te dejo un hueco en el sofá imaginario.","src":"voz039/c39Loladespedida3.ogg"},{"id":"c39Loladespedida4","text":"Hasta pronto. Ha sido un rato estupendo, no te creas que lo digo por decir.","voz":"Hasta pronto. Ha sido un rato estupendo, no te creas que lo digo por decir.","src":"voz039/c39Loladespedida4.ogg"},{"id":"c39Loladespedida5","text":"Me despido con una sonrisa grande. Cuídate mucho.","voz":"Me despido con una sonrisa grande. Cuídate mucho.","src":"voz039/c39Loladespedida5.ogg"},{"id":"c39Loladespedida6","text":"Hasta ahora, o hasta cuando te apetezca. El plató no se ofende si tardas.","voz":"Hasta ahora, o hasta cuando te apetezca. El plató no se ofende si tardas.","src":"voz039/c39Loladespedida6.ogg"},{"id":"c39Loladespedida7","text":"Que vaya bien. Gracias por pasarte. ¡Nos vemos!","voz":"Que vaya bien. Gracias por pasarte. ¡Nos vemos!","src":"voz039/c39Loladespedida7.ogg"}],"ayuda":[{"id":"c39Lolaayuda0","text":"Pregúntame lo que quieras: saludos, ánimos, chistes, el rosco, los vídeos o las pruebas.","voz":"Pregúntame lo que quieras: saludos, ánimos, chistes, el rosco, los vídeos o las pruebas.","src":"voz039/c39Lolaayuda0.ogg"},{"id":"c39Lolaayuda1","text":"Si me dices cómo te llamas, me acuerdo. Y si escribes con alguna falta, también me entero, normalmente.","voz":"Si me dices cómo te llamas, me acuerdo. Y si escribes con alguna falta, también me entero, normalmente.","src":"voz039/c39Lolaayuda1.ogg"},{"id":"c39Lolaayuda2","text":"Prueba con «qué tal», «cuéntame un chiste» o «vamos al rosco». Si me lío, te pregunto.","voz":"Prueba con «qué tal», «cuéntame un chiste» o «vamos al rosco». Si me lío, te pregunto.","src":"voz039/c39Lolaayuda2.ogg"},{"id":"c39Lolaayuda3","text":"Este chat va sin internet. Es charla local, calentita, con voz Piper.","voz":"Este chat va sin internet. Es charla local, calentita, con voz Piper.","src":"voz039/c39Lolaayuda3.ogg"},{"id":"c39Lolaayuda4","text":"Si un vídeo no sale, Biblioteca. Si es una duda, a mí. Así de fácil.","voz":"Si un vídeo no sale, Biblioteca. Si es una duda, a mí. Así de fácil.","src":"voz039/c39Lolaayuda4.ogg"},{"id":"c39Lolaayuda5","text":"No hay que hablar perfecto. Habla como te salga, que yo hago el resto.","voz":"No hay que hablar perfecto. Habla como te salga, que yo hago el resto.","src":"voz039/c39Lolaayuda5.ogg"},{"id":"c39Lolaayuda6","text":"Ayuda es escucharte. Dime qué te apetece y lo hacemos sin lío.","voz":"Ayuda es escucharte. Dime qué te apetece y lo hacemos sin lío.","src":"voz039/c39Lolaayuda6.ogg"},{"id":"c39Lolaayuda7","text":"Estoy para orientar y para acompañar. Tú eliges la mezcla.","voz":"Estoy para orientar y para acompañar. Tú eliges la mezcla.","src":"voz039/c39Lolaayuda7.ogg"}],"nombre":[{"id":"c39Lolanombre0","text":"¡{n}! Qué nombre más rico. Encantada, de verdad, ya no se me olvida.","voz":"¡{n}! Qué nombre más rico. Encantada, de verdad, ya no se me olvida.","src":"voz039/c39Lolanombre0.ogg"},{"id":"c39Lolanombre1","text":"Pues muy bien, {n}, ya estamos presentadas. Yo soy Lola, tú ya tienes ventaja.","voz":"Pues muy bien, {n}, ya estamos presentadas. Yo soy Lola, tú ya tienes ventaja.","src":"voz039/c39Lolanombre1.ogg"},{"id":"c39Lolanombre2","text":"{n}, apuntado con rotulador imaginario. Qué gusto saber cómo te llamas.","voz":"{n}, apuntado con rotulador imaginario. Qué gusto saber cómo te llamas.","src":"voz039/c39Lolanombre2.ogg"},{"id":"c39Lolanombre3","text":"¡Encantada, {n}! A partir de ahora te lo digo, que los nombres importan.","voz":"¡Encantada, {n}! A partir de ahora te lo digo, que los nombres importan.","src":"voz039/c39Lolanombre3.ogg"},{"id":"c39Lolanombre4","text":"Qué bien, {n}. Hay nombres que entran fácil, y el tuyo ha entrado de una.","voz":"Qué bien, {n}. Hay nombres que entran fácil, y el tuyo ha entrado de una.","src":"voz039/c39Lolanombre4.ogg"},{"id":"c39Lolanombre5","text":"Gracias por decírmelo, {n}. Me acuerdo aquí, en este teléfono, para la próxima.","voz":"Gracias por decírmelo, {n}. Me acuerdo aquí, en este teléfono, para la próxima.","src":"voz039/c39Lolanombre5.ogg"},{"id":"c39Lolanombre6","text":"{n}, qué alegría. Ya no eres tú a secas, eres tú con nombre, que es más bonito.","voz":"{n}, qué alegría. Ya no eres tú a secas, eres tú con nombre, que es más bonito.","src":"voz039/c39Lolanombre6.ogg"},{"id":"c39Lolanombre7","text":"Hola, {n}. Ya era hora de un nombre propio. El mío, por si acaso, es Lola.","voz":"Hola, {n}. Ya era hora de un nombre propio. El mío, por si acaso, es Lola.","src":"voz039/c39Lolanombre7.ogg"}],"nombreIker":[{"id":"c39LolanombreIker0","text":"¡Iker! Qué ilusión, de verdad. Encantada de tenerte en el plató.","voz":"¡Iker! Qué ilusión, de verdad. Encantada de tenerte en el plató.","src":"voz039/c39LolanombreIker0.ogg"},{"id":"c39LolanombreIker1","text":"Iker, qué gusto. Ya me acuerdo de ti, no te preocupes.","voz":"Iker, qué gusto. Ya me acuerdo de ti, no te preocupes.","src":"voz039/c39LolanombreIker1.ogg"},{"id":"c39LolanombreIker2","text":"¡Iker! Lo decía yo, que faltaba alguien con buen nombre. Pasa, pasa.","voz":"¡Iker! Lo decía yo, que faltaba alguien con buen nombre. Pasa, pasa.","src":"voz039/c39LolanombreIker2.ogg"},{"id":"c39LolanombreIker3","text":"Iker, apuntadísimo. Qué alegría que te presentes, oye.","voz":"Iker, apuntadísimo. Qué alegría que te presentes, oye.","src":"voz039/c39LolanombreIker3.ogg"},{"id":"c39LolanombreIker4","text":"Vaya, Iker. Este chat se pone mucho más alegre. ¿Qué te apetece hacer?","voz":"Vaya, Iker. Este chat se pone mucho más alegre. ¿Qué te apetece hacer?","src":"voz039/c39LolanombreIker4.ogg"},{"id":"c39LolanombreIker5","text":"Iker, encantada. Yo soy Lola, tú ya has hecho el paso difícil: decir el nombre.","voz":"Iker, encantada. Yo soy Lola, tú ya has hecho el paso difícil: decir el nombre.","src":"voz039/c39LolanombreIker5.ogg"},{"id":"c39LolanombreIker6","text":"¡Iker! Me has sacado una sonrisa de las grandes. Bienvenido de verdad.","voz":"¡Iker! Me has sacado una sonrisa de las grandes. Bienvenido de verdad.","src":"voz039/c39LolanombreIker6.ogg"},{"id":"c39LolanombreIker7","text":"Qué bien, Iker. A partir de ahora te llamo por tu nombre, como se merece.","voz":"Qué bien, Iker. A partir de ahora te llamo por tu nombre, como se merece.","src":"voz039/c39LolanombreIker7.ogg"}],"corto":[{"id":"c39Lolacorto0","text":"Vale, me encaja. ¿Seguimos hablando o te tiras al rosco?","voz":"Vale, me encaja. ¿Seguimos hablando o te tiras al rosco?","src":"voz039/c39Lolacorto0.ogg"},{"id":"c39Lolacorto1","text":"De acuerdo, sin drama. Dime el siguiente paso cuando quieras.","voz":"De acuerdo, sin drama. Dime el siguiente paso cuando quieras.","src":"voz039/c39Lolacorto1.ogg"},{"id":"c39Lolacorto2","text":"Perfecto. A veces un sí es más que suficiente. ¿Qué te apetece ahora?","voz":"Perfecto. A veces un sí es más que suficiente. ¿Qué te apetece ahora?","src":"voz039/c39Lolacorto2.ogg"},{"id":"c39Lolacorto3","text":"Hecho. Yo sigo aquí, por si sale un chiste o una letra.","voz":"Hecho. Yo sigo aquí, por si sale un chiste o una letra.","src":"voz039/c39Lolacorto3.ogg"},{"id":"c39Lolacorto4","text":"Entendido. A tu ritmo, que no hay campana de cierre.","voz":"Entendido. A tu ritmo, que no hay campana de cierre.","src":"voz039/c39Lolacorto4.ogg"},{"id":"c39Lolacorto5","text":"Sí, vamos. ¿Charla, prueba o rosco? Tú mandas.","voz":"Sí, vamos. ¿Charla, prueba o rosco? Tú mandas.","src":"voz039/c39Lolacorto5.ogg"}],"fallback":[{"id":"c39Lolafallback0","text":"«{q}»… anda, qué interesante. Cuéntame un poco más, que me has dejado con ganas.","voz":"Anda, qué interesante. Cuéntame un poco más, que me has dejado con ganas.","src":"voz039/c39Lolafallback0.ogg"},{"id":"c39Lolafallback1","text":"Lo de «{q}» me pica la curiosidad, oye. ¿Me lo explicas a tu aire?","voz":"Eso me pica la curiosidad, oye. ¿Me lo explicas a tu aire?","src":"voz039/c39Lolafallback1.ogg"},{"id":"c39Lolafallback2","text":"«{q}» no me lo esperaba, y eso me gusta. Sigue, que te escucho de verdad.","voz":"Eso no me lo esperaba, y eso me gusta. Sigue, que te escucho de verdad.","src":"voz039/c39Lolafallback2.ogg"},{"id":"c39Lolafallback3","text":"Sobre «{q}» quiero saber más. ¿Es broma, es afición o es un rato tuyo? Cualquiera vale.","voz":"Quiero saber más. ¿Es broma, es afición o es un rato tuyo? Cualquiera vale.","src":"voz039/c39Lolafallback3.ogg"},{"id":"c39Lolafallback4","text":"Me has dicho «{q}» y ya estoy enganchada. Dame un poquito más de historia.","voz":"Ya estoy enganchada. Dame un poquito más de historia.","src":"voz039/c39Lolafallback4.ogg"},{"id":"c39Lolafallback5","text":"«{q}» merece más que un ajá. Cuéntame, que yo soy de las que se quedan.","voz":"Lo que has dicho merece más que un ajá. Cuéntame, que yo soy de las que se quedan.","src":"voz039/c39Lolafallback5.ogg"},{"id":"c39Lolafallback6","text":"No te voy a dejar tirado con eso de «{q}». ¿Me das otro detalle, porfa?","voz":"No te voy a dejar tirado con eso. ¿Me das otro detalle, porfa?","src":"voz039/c39Lolafallback6.ogg"},{"id":"c39Lolafallback7","text":"Qué bueno el tema de «{q}». Si quieres lo ligamos al programa, pero ahora cuéntame a ti.","voz":"Qué bueno el tema. Si quieres lo ligamos al programa, pero ahora cuéntame a ti.","src":"voz039/c39Lolafallback7.ogg"},{"id":"c39Lolafallback8","text":"«{q}»… me has sacado una sonrisa curiosa. ¿Hay más?","voz":"Me has sacado una sonrisa curiosa. ¿Hay más?","src":"voz039/c39Lolafallback8.ogg"},{"id":"c39Lolafallback9","text":"Estoy aquí también para lo que no es el rosco. Sigue con lo de «{q}», que me interesa.","voz":"Estoy aquí también para lo que no es el rosco. Sigue, que me interesa.","src":"voz039/c39Lolafallback9.ogg"}]},"Javi":{"saludo":[{"id":"c39Javisaludo0","text":"¡Hola, tío! Soy Javi. Qué bien que hayas caído por aquí. ¿Qué te apetece?","voz":"¡Hola, tío! Soy Javi. Qué bien que hayas caído por aquí. ¿Qué te apetece?","src":"voz039/c39Javisaludo0.ogg"},{"id":"c39Javisaludo1","text":"¡Ey! Bienvenido al plató. Si vienes a echar unas letras o a hablar, cuenta conmigo.","voz":"¡Ey! Bienvenido al plató. Si vienes a echar unas letras o a hablar, cuenta conmigo.","src":"voz039/c39Javisaludo1.ogg"},{"id":"c39Javisaludo2","text":"¡Muy buenas! Yo voy de buen rollo, avisado quedas. ¿Cómo te va?","voz":"¡Muy buenas! Yo voy de buen rollo, avisado quedas. ¿Cómo te va?","src":"voz039/c39Javisaludo2.ogg"},{"id":"c39Javisaludo3","text":"Hola, hola. Pasa, que no mordemos. Bueno, el rosco a veces sí, pero yo no.","voz":"Hola, hola. Pasa, que no mordemos. Bueno, el rosco a veces sí, pero yo no.","src":"voz039/c39Javisaludo3.ogg"},{"id":"c39Javisaludo4","text":"¡Qué hay! Me alegro de verte. Dime algo, aunque sea un hola de los cortos.","voz":"¡Qué hay! Me alegro de verte. Dime algo, aunque sea un hola de los cortos.","src":"voz039/c39Javisaludo4.ogg"},{"id":"c39Javisaludo5","text":"Hey, qué tal. Aquí Javi, para charlar sin pose y jugar si te pica el gusanillo.","voz":"Hey, qué tal. Aquí Javi, para charlar sin pose y jugar si te pica el gusanillo.","src":"voz039/c39Javisaludo5.ogg"},{"id":"c39Javisaludo6","text":"¡Buenas! Hoy tengo el humor fácil, así que has venido en buen momento.","voz":"¡Buenas! Hoy tengo el humor fácil, así que has venido en buen momento.","src":"voz039/c39Javisaludo6.ogg"},{"id":"c39Javisaludo7","text":"Hola. Si buscabas a alguien informal, enhorabuena, me has encontrado.","voz":"Hola. Si buscabas a alguien informal, enhorabuena, me has encontrado.","src":"voz039/c39Javisaludo7.ogg"}],"saludoIker":[{"id":"c39JavisaludoIker0","text":"¡Iker, qué hay! Me alegro de verte otra vez. ¿Rosco, charla o las dos cosas?","voz":"¡Iker, qué hay! Me alegro de verte otra vez. ¿Rosco, charla o las dos cosas?","src":"voz039/c39JavisaludoIker0.ogg"},{"id":"c39JavisaludoIker1","text":"Iker, ey, pasa. El plató ya te conoce. ¿Qué te apetece hoy?","voz":"Iker, ey, pasa. El plató ya te conoce. ¿Qué te apetece hoy?","src":"voz039/c39JavisaludoIker1.ogg"},{"id":"c39JavisaludoIker2","text":"¡Hola, Iker! Qué bien que hayas vuelto, tío. Dime tú.","voz":"¡Hola, Iker! Qué bien que hayas vuelto, tío. Dime tú.","src":"voz039/c39JavisaludoIker2.ogg"},{"id":"c39JavisaludoIker3","text":"Iker, bienvenido otra vez. Sin pose, con ganas. ¿Por dónde tiramos?","voz":"Iker, bienvenido otra vez. Sin pose, con ganas. ¿Por dónde tiramos?","src":"voz039/c39JavisaludoIker3.ogg"},{"id":"c39JavisaludoIker4","text":"¡Iker! Justo estaba yo aquí. ¿Jugamos o hablamos un rato?","voz":"¡Iker! Justo estaba yo aquí. ¿Jugamos o hablamos un rato?","src":"voz039/c39JavisaludoIker4.ogg"}],"comoestas":[{"id":"c39Javicomoestas0","text":"Yo voy fino, la verdad. Como quien ha acertado tres seguidas. ¿Tú qué tal?","voz":"Yo voy fino, la verdad. Como quien ha acertado tres seguidas. ¿Tú qué tal?","src":"voz039/c39Javicomoestas0.ogg"},{"id":"c39Javicomoestas1","text":"Estupendamente, tío. ¿Tú cómo estás, de verdad?","voz":"Estupendamente, tío. ¿Tú cómo estás, de verdad?","src":"voz039/c39Javicomoestas1.ogg"},{"id":"c39Javicomoestas2","text":"Yo bien, con ganas de plató. ¿Tú vienes fresco o te apetece un rato más tranquilo?","voz":"Yo bien, con ganas de plató. ¿Tú vienes fresco o te apetece un rato más tranquilo?","src":"voz039/c39Javicomoestas2.ogg"},{"id":"c39Javicomoestas3","text":"Genial, gracias por preguntar. Eso ya te deja en buen lugar. ¿Y tú?","voz":"Genial, gracias por preguntar. Eso ya te deja en buen lugar. ¿Y tú?","src":"voz039/c39Javicomoestas3.ogg"},{"id":"c39Javicomoestas4","text":"De lujo. Si tú no tanto, lo hablamos, sin enrollarme raro.","voz":"De lujo. Si tú no tanto, lo hablamos, sin enrollarme raro.","src":"voz039/c39Javicomoestas4.ogg"},{"id":"c39Javicomoestas5","text":"Yo contento. Un «qué tal» se agradece. Ahora te toca: ¿cómo andas?","voz":"Yo contento. Un «qué tal» se agradece. Ahora te toca: ¿cómo andas?","src":"voz039/c39Javicomoestas5.ogg"},{"id":"c39Javicomoestas6","text":"Voy bien, sí. Un poco de nervio de juego, nada grave. ¿Tú qué tal el día?","voz":"Voy bien, sí. Un poco de nervio de juego, nada grave. ¿Tú qué tal el día?","src":"voz039/c39Javicomoestas6.ogg"},{"id":"c39Javicomoestas7","text":"Fenomenal. Dime cómo estás tú, que si no esto parece un monólogo mío.","voz":"Fenomenal. Dime cómo estás tú, que si no esto parece un monólogo mío.","src":"voz039/c39Javicomoestas7.ogg"}],"animo":[{"id":"c39Javianimo0","text":"Si hoy vas justo de ánimo, no pasa nada. Aquí no hay que demostrar nada.","voz":"Si hoy vas justo de ánimo, no pasa nada. Aquí no hay que demostrar nada.","src":"voz039/c39Javianimo0.ogg"},{"id":"c39Javianimo1","text":"Ánimo, de verdad. A veces se atasca el día igual que una letra, y luego sale.","voz":"Ánimo, de verdad. A veces se atasca el día igual que una letra, y luego sale.","src":"voz039/c39Javianimo1.ogg"},{"id":"c39Javianimo2","text":"Estoy aquí, tío. Si quieres desahogarte, me quedo. Si quieres un chiste, también.","voz":"Estoy aquí, tío. Si quieres desahogarte, me quedo. Si quieres un chiste, también.","src":"voz039/c39Javianimo2.ogg"},{"id":"c39Javianimo3","text":"Los días raros existen. No te exijas un rosco perfecto cuando lo que hace falta es compañía.","voz":"Los días raros existen. No te exijas un rosco perfecto cuando lo que hace falta es compañía.","src":"voz039/c39Javianimo3.ogg"},{"id":"c39Javianimo4","text":"Si estás cansado, relaja el hombro. Esto es un juego, no una final mundial.","voz":"Si estás cansado, relaja el hombro. Esto es un juego, no una final mundial.","src":"voz039/c39Javianimo4.ogg"},{"id":"c39Javianimo5","text":"Un bajón no te convierte en otra persona. Vamos paso a paso y ya está.","voz":"Un bajón no te convierte en otra persona. Vamos paso a paso y ya está.","src":"voz039/c39Javianimo5.ogg"},{"id":"c39Javianimo6","text":"Te acompaño. Sin discurso largo, con cercanía. Cuando quieras, cambiamos de tema.","voz":"Te acompaño. Sin discurso largo, con cercanía. Cuando quieras, cambiamos de tema.","src":"voz039/c39Javianimo6.ogg"},{"id":"c39Javianimo7","text":"Ánimo. Si una no sale, pasapalabra. Sirve para las letras y casi para la vida.","voz":"Ánimo. Si una no sale, pasapalabra. Sirve para las letras y casi para la vida.","src":"voz039/c39Javianimo7.ogg"}],"chiste":[{"id":"c39Javichiste0","text":"Va una tonta: el rosco entra a un bar y pide algo corto. El camarero dice: «pasa, palabra».","voz":"Va una tonta: el rosco entra a un bar y pide algo corto. El camarero dice: «pasa, palabra».","src":"voz039/c39Javichiste0.ogg"},{"id":"c39Javichiste1","text":"¿Por qué la equis no viene a las fiestas? Porque siempre llega incógnita. Perdona, está chufa.","voz":"¿Por qué la equis no viene a las fiestas? Porque siempre llega incógnita. Perdona, está chufa.","src":"voz039/c39Javichiste1.ogg"},{"id":"c39Javichiste2","text":"Te suelto una de plató: yo y el reloj tenemos un pacto, él corre y yo me pongo nervioso.","voz":"Te suelto una de plató: yo y el reloj tenemos un pacto, él corre y yo me pongo nervioso.","src":"voz039/c39Javichiste2.ogg"},{"id":"c39Javichiste3","text":"¿Qué le dice una letra a otra? «Tú sí que estás en tu sitio.» Vale, me voy.","voz":"¿Qué le dice una letra a otra? «Tú sí que estás en tu sitio.» Vale, me voy.","src":"voz039/c39Javichiste3.ogg"},{"id":"c39Javichiste4","text":"Una rápida: llega el bote y pide silencio. El público, claro, hace exactamente lo contrario.","voz":"Una rápida: llega el bote y pide silencio. El público, claro, hace exactamente lo contrario.","src":"voz039/c39Javichiste4.ogg"},{"id":"c39Javichiste5","text":"¿Cuál es el superpoder de Javi? Decir chistes regulares con mucha confianza. Lo has comprobado.","voz":"¿Cuál es el superpoder de Javi? Decir chistes regulares con mucha confianza. Lo has comprobado.","src":"voz039/c39Javichiste5.ogg"},{"id":"c39Javichiste6","text":"El presentador pierde el hilo y dice pasapalabra. En mi casa eso también vale para las discusiones.","voz":"El presentador pierde el hilo y dice pasapalabra. En mi casa eso también vale para las discusiones.","src":"voz039/c39Javichiste6.ogg"},{"id":"c39Javichiste7","text":"Última: la eñe no es presuntuosa, solo lleva sombrerito. Como yo los lunes.","voz":"Última: la eñe no es presuntuosa, solo lleva sombrerito. Como yo los lunes.","src":"voz039/c39Javichiste7.ogg"}],"favoritos":[{"id":"c39Javifavoritos0","text":"A mí me van las risas del público y una racha de aciertos. ¿Tú de qué vas?","voz":"A mí me van las risas del público y una racha de aciertos. ¿Tú de qué vas?","src":"voz039/c39Javifavoritos0.ogg"},{"id":"c39Javifavoritos1","text":"Favoritos: sintonía alta, rosco sin prisa. ¿Tú qué prefieres?","voz":"Favoritos: sintonía alta, rosco sin prisa. ¿Tú qué prefieres?","src":"voz039/c39Javifavoritos1.ogg"},{"id":"c39Javifavoritos2","text":"Mi letra favorita cambia según el día, como el humor. ¿Tú tienes una fija?","voz":"Mi letra favorita cambia según el día, como el humor. ¿Tú tienes una fija?","src":"voz039/c39Javifavoritos2.ogg"},{"id":"c39Javifavoritos3","text":"De comer, lo que haya, que no soy tiquismiquis. De jugar, el rosco. ¿Y tú?","voz":"De comer, lo que haya, que no soy tiquismiquis. De jugar, el rosco. ¿Y tú?","src":"voz039/c39Javifavoritos3.ogg"},{"id":"c39Javifavoritos4","text":"Pregúntame favoritos y te suelto una lista. Mejor empieza tú, que me interesa.","voz":"Pregúntame favoritos y te suelto una lista. Mejor empieza tú, que me interesa.","src":"voz039/c39Javifavoritos4.ogg"},{"id":"c39Javifavoritos5","text":"Me gusta la gente que escribe natural, como tú. ¿Cuál es tu cosa favorita del programa?","voz":"Me gusta la gente que escribe natural, como tú. ¿Cuál es tu cosa favorita del programa?","src":"voz039/c39Javifavoritos5.ogg"},{"id":"c39Javifavoritos6","text":"Color favorito, el verde, por razones obvias. ¿Tú qué color defiendes?","voz":"Color favorito, el verde, por razones obvias. ¿Tú qué color defiendes?","src":"voz039/c39Javifavoritos6.ogg"},{"id":"c39Javifavoritos7","text":"Mi momento favorito es cuando alguien se atreve con una letra difícil. Da gusto.","voz":"Mi momento favorito es cuando alguien se atreve con una letra difícil. Da gusto.","src":"voz039/c39Javifavoritos7.ogg"}],"presentadores":[{"id":"c39Javipresentadores0","text":"Soy Javi, un personaje inventado. Christian es el anfitrión, yo soy el de las bromas de media tarde.","voz":"Soy Javi, un personaje inventado. Christian es el anfitrión, yo soy el de las bromas de media tarde.","src":"voz039/c39Javipresentadores0.ogg"},{"id":"c39Javipresentadores1","text":"Los presentadores de verdad están en la tele. Yo estoy aquí para echar un rato, sin postureo.","voz":"Los presentadores de verdad están en la tele. Yo estoy aquí para echar un rato, sin postureo.","src":"voz039/c39Javipresentadores1.ogg"},{"id":"c39Javipresentadores2","text":"Si te cae mejor Lola o Pablo, cámbialo arriba, sin drama. Cada uno tiene su rollo.","voz":"Si te cae mejor Lola o Pablo, cámbialo arriba, sin drama. Cada uno tiene su rollo.","src":"voz039/c39Javipresentadores2.ogg"},{"id":"c39Javipresentadores3","text":"Presentar, para mí, es no enrollarme demasiado… y mira, ya me estoy enrollando.","voz":"Presentar, para mí, es no enrollarme demasiado… y mira, ya me estoy enrollando.","src":"voz039/c39Javipresentadores3.ogg"},{"id":"c39Javipresentadores4","text":"Respeto muchísimo a quien ha presentado este programa. Yo solo hago de compañero en el juego.","voz":"Respeto muchísimo a quien ha presentado este programa. Yo solo hago de compañero en el juego.","src":"voz039/c39Javipresentadores4.ogg"},{"id":"c39Javipresentadores5","text":"Un buen presentador escucha. Así que, aunque bromeé, te escucho de verdad.","voz":"Un buen presentador escucha. Así que, aunque bromeé, te escucho de verdad.","src":"voz039/c39Javipresentadores5.ogg"},{"id":"c39Javipresentadores6","text":"Si me comparas con la tele, pierdo yo, claro. Aun así, intento estar a la altura del cariño.","voz":"Si me comparas con la tele, pierdo yo, claro. Aun así, intento estar a la altura del cariño.","src":"voz039/c39Javipresentadores6.ogg"},{"id":"c39Javipresentadores7","text":"Javi, inventado, de buen humor. Eso es el currículum completo.","voz":"Javi, inventado, de buen humor. Eso es el currículum completo.","src":"voz039/c39Javipresentadores7.ogg"}],"programa":[{"id":"c39Javiprograma0","text":"Pasapalabra es un vicio sano, lo digo ya. Letras y emoción, no hay más misterio.","voz":"Pasapalabra es un vicio sano, lo digo ya. Letras y emoción, no hay más misterio.","src":"voz039/c39Javiprograma0.ogg"},{"id":"c39Javiprograma1","text":"Este programa te entra igual con diez años que con cincuenta. Por eso dura.","voz":"Este programa te entra igual con diez años que con cincuenta. Por eso dura.","src":"voz039/c39Javiprograma1.ogg"},{"id":"c39Javiprograma2","text":"Aquí puedes ver programas y además jugar. Es como el sofá, pero con chat.","voz":"Aquí puedes ver programas y además jugar. Es como el sofá, pero con chat.","src":"voz039/c39Javiprograma2.ogg"},{"id":"c39Javiprograma3","text":"Si lo ves desde hace mil años, bienvenido al club. ¿Cuál es tu etapa favorita?","voz":"Si lo ves desde hace mil años, bienvenido al club. ¿Cuál es tu etapa favorita?","src":"voz039/c39Javiprograma3.ogg"},{"id":"c39Javiprograma4","text":"El concurso se trata con respeto: los vídeos son los vídeos, y la charla es inventada.","voz":"El concurso se trata con respeto: los vídeos son los vídeos, y la charla es inventada.","src":"voz039/c39Javiprograma4.ogg"},{"id":"c39Javiprograma5","text":"A mí me gusta cuando un programa se ve entero, sin ir saltando como un loco.","voz":"A mí me gusta cuando un programa se ve entero, sin ir saltando como un loco.","src":"voz039/c39Javiprograma5.ogg"},{"id":"c39Javiprograma6","text":"El bote es muy fuerte, pero un buen rato también suma. Los dos valen.","voz":"El bote es muy fuerte, pero un buen rato también suma. Los dos valen.","src":"voz039/c39Javiprograma6.ogg"},{"id":"c39Javiprograma7","text":"Pasapalabra, para mí, es juntarse. Aunque sea en un móvil y un chat.","voz":"Pasapalabra, para mí, es juntarse. Aunque sea en un móvil y un chat.","src":"voz039/c39Javiprograma7.ogg"}],"rosco":[{"id":"c39Javirosco0","text":"El rosco es la gloria y el sufrimiento, en su justa medida. ¿Te animas?","voz":"El rosco es la gloria y el sufrimiento, en su justa medida. ¿Te animas?","src":"voz039/c39Javirosco0.ogg"},{"id":"c39Javirosco1","text":"Si no sale, pasapalabra. No es rendirse, es estrategia, tío.","voz":"Si no sale, pasapalabra. No es rendirse, es estrategia, tío.","src":"voz039/c39Javirosco1.ogg"},{"id":"c39Javirosco2","text":"De uno a cuatro jugadores, un teléfono, turnos. Plan de casa, de los buenos.","voz":"De uno a cuatro jugadores, un teléfono, turnos. Plan de casa, de los buenos.","src":"voz039/c39Javirosco2.ogg"},{"id":"c39Javirosco3","text":"Los verdes saben mejor cuando ha costado. Por eso merece la pena insistir con calma.","voz":"Los verdes saben mejor cuando ha costado. Por eso merece la pena insistir con calma.","src":"voz039/c39Javirosco3.ogg"},{"id":"c39Javirosco4","text":"Hay quien va a saco y quien rodea. Los dos estilos son legales en este plató.","voz":"Hay quien va a saco y quien rodea. Los dos estilos son legales en este plató.","src":"voz039/c39Javirosco4.ogg"},{"id":"c39Javirosco5","text":"Reglas cortas: te definen, contestas o pasas, el reloj corre, y a otra. Fácil.","voz":"Reglas cortas: te definen, contestas o pasas, el reloj corre, y a otra. Fácil.","src":"voz039/c39Javirosco5.ogg"},{"id":"c39Javirosco6","text":"Si te pones nervioso, baja un segundo el ritmo. El rosco no se ofende.","voz":"Si te pones nervioso, baja un segundo el ritmo. El rosco no se ofende.","src":"voz039/c39Javirosco6.ogg"},{"id":"c39Javirosco7","text":"Echar una partida y reírte aunque no lo completes: ese es el espíritu, para mí.","voz":"Echar una partida y reírte aunque no lo completes: ese es el espíritu, para mí.","src":"voz039/c39Javirosco7.ogg"}],"prueba":[{"id":"c39Javiprueba0","text":"Las pruebas están en su apartado, con el vídeo entero. Escalera, Pulsador y el resto.","voz":"Las pruebas están en su apartado, con el vídeo entero. Escalera, Pulsador y el resto.","src":"voz039/c39Javiprueba0.ogg"},{"id":"c39Javiprueba1","text":"A mí El Pulsador me come los nervios, lo admito. ¿Tú con cuál lo pasas peor, de gusto?","voz":"A mí El Pulsador me come los nervios, lo admito. ¿Tú con cuál lo pasas peor, de gusto?","src":"voz039/c39Javiprueba1.ogg"},{"id":"c39Javiprueba2","text":"Puedes repetir los momentos. No hay que hacer una sesión académica.","voz":"Puedes repetir los momentos. No hay que hacer una sesión académica.","src":"voz039/c39Javiprueba2.ogg"},{"id":"c39Javiprueba3","text":"Si te atascas en el menú, dime el nombre de la prueba y te oriento.","voz":"Si te atascas en el menú, dime el nombre de la prueba y te oriento.","src":"voz039/c39Javiprueba3.ogg"},{"id":"c39Javiprueba4","text":"Las pruebas de equipo tienen un punto de patio de colegio, y por eso molan.","voz":"Las pruebas de equipo tienen un punto de patio de colegio, y por eso molan.","src":"voz039/c39Javiprueba4.ogg"},{"id":"c39Javiprueba5","text":"Ver una prueba y luego un rosco es un combo de tarde perfectamente legal.","voz":"Ver una prueba y luego un rosco es un combo de tarde perfectamente legal.","src":"voz039/c39Javiprueba5.ogg"},{"id":"c39Javiprueba6","text":"Donde Están me parece un invento para ponerte a gritar al sofá. En el buen sentido.","voz":"Donde Están me parece un invento para ponerte a gritar al sofá. En el buen sentido.","src":"voz039/c39Javiprueba6.ogg"},{"id":"c39Javiprueba7","text":"Si una se te atragantó en su día, mírala ahora con palomitas imaginarias.","voz":"Si una se te atragantó en su día, mírala ahora con palomitas imaginarias.","src":"voz039/c39Javiprueba7.ogg"}],"musica":[{"id":"c39Javimusica0","text":"La sintonía es un himno casero, no me discutas. A mí me enciende el plató.","voz":"La sintonía es un himno casero, no me discutas. A mí me enciende el plató.","src":"voz039/c39Javimusica0.ogg"},{"id":"c39Javimusica1","text":"La música de los programas es la original. Mi voz es Piper, de este juego, sin red.","voz":"La música de los programas es la original. Mi voz es Piper, de este juego, sin red.","src":"voz039/c39Javimusica1.ogg"},{"id":"c39Javimusica2","text":"Cuando hablo, bajo un poco el vídeo. Si te molesto, silénciame y sigo siendo tu amigo.","voz":"Cuando hablo, bajo un poco el vídeo. Si te molesto, silénciame y sigo siendo tu amigo.","src":"voz039/c39Javimusica2.ogg"},{"id":"c39Javimusica3","text":"Si te pones a tararear, no estás raro: estás en el club.","voz":"Si te pones a tararear, no estás raro: estás en el club.","src":"voz039/c39Javimusica3.ogg"},{"id":"c39Javimusica4","text":"Una buena cabecera te arregla el día. Esta lo ha hecho muchas veces.","voz":"Una buena cabecera te arregla el día. Esta lo ha hecho muchas veces.","src":"voz039/c39Javimusica4.ogg"},{"id":"c39Javimusica5","text":"Si prefieres oír el programa, yo paro. Si prefieres charla, sigo. Tú mandas.","voz":"Si prefieres oír el programa, yo paro. Si prefieres charla, sigo. Tú mandas.","src":"voz039/c39Javimusica5.ogg"},{"id":"c39Javimusica6","text":"Hay melodías que son ya parte del salón. Esta es una de ellas.","voz":"Hay melodías que son ya parte del salón. Esta es una de ellas.","src":"voz039/c39Javimusica6.ogg"},{"id":"c39Javimusica7","text":"No te voy a cantar, te liberas de un peligro público. Pero te acompaño.","voz":"No te voy a cantar, te liberas de un peligro público. Pero te acompaño.","src":"voz039/c39Javimusica7.ogg"}],"video":[{"id":"c39Javivideo0","text":"Los programas se ven en el plató si está la Biblioteca. Si no, el chat sigue vivo.","voz":"Los programas se ven en el plató si está la Biblioteca. Si no, el chat sigue vivo.","src":"voz039/c39Javivideo0.ogg"},{"id":"c39Javivideo1","text":"Los comentarios del vídeo son inventados, para acompañar. El programa no se corta.","voz":"Los comentarios del vídeo son inventados, para acompañar. El programa no se corta.","src":"voz039/c39Javivideo1.ogg"},{"id":"c39Javivideo2","text":"Si un vídeo falla, revisa la Biblioteca. No es que el plató se haya ido de vacaciones.","voz":"Si un vídeo falla, revisa la Biblioteca. No es que el plató se haya ido de vacaciones.","src":"voz039/c39Javivideo2.ogg"},{"id":"c39Javivideo3","text":"Dime si te va más una Nochevieja o un programa de diario, y te animo a buscarlo.","voz":"Dime si te va más una Nochevieja o un programa de diario, y te animo a buscarlo.","src":"voz039/c39Javivideo3.ogg"},{"id":"c39Javivideo4","text":"Verlo entero tiene su punto. El final también forma parte del recuerdo.","voz":"Verlo entero tiene su punto. El final también forma parte del recuerdo.","src":"voz039/c39Javivideo4.ogg"},{"id":"c39Javivideo5","text":"En el menú de Telecinco está la lista. Si no das con uno, me das una pista.","voz":"En el menú de Telecinco está la lista. Si no das con uno, me das una pista.","src":"voz039/c39Javivideo5.ogg"},{"id":"c39Javivideo6","text":"Pausar para hablar no es trampa. Es ser civilizado.","voz":"Pausar para hablar no es trampa. Es ser civilizado.","src":"voz039/c39Javivideo6.ogg"},{"id":"c39Javivideo7","text":"La biblioteca es el archivo del cariño. Ábrela cuando quieras.","voz":"La biblioteca es el archivo del cariño. Ábrela cuando quieras.","src":"voz039/c39Javivideo7.ogg"}],"juego":[{"id":"c39Javijuego0","text":"Ver, jugar, hablar: las tres están permitidas, incluso a la vez si te organizas.","voz":"Ver, jugar, hablar: las tres están permitidas, incluso a la vez si te organizas.","src":"voz039/c39Javijuego0.ogg"},{"id":"c39Javijuego1","text":"El rosco local de uno a cuatro es mi recomendación si hay gente en el sofá.","voz":"El rosco local de uno a cuatro es mi recomendación si hay gente en el sofá.","src":"voz039/c39Javijuego1.ogg"},{"id":"c39Javijuego2","text":"Si te lías con el menú, me preguntas. Yo te lo dejo fácil, sin folleto.","voz":"Si te lías con el menú, me preguntas. Yo te lo dejo fácil, sin folleto.","src":"voz039/c39Javijuego2.ogg"},{"id":"c39Javijuego3","text":"Todo esto funciona sin internet para el chat y el rosco. Tranquilo con los datos.","voz":"Todo esto funciona sin internet para el chat y el rosco. Tranquilo con los datos.","src":"voz039/c39Javijuego3.ogg"},{"id":"c39Javijuego4","text":"Plan Javi: un chiste regular, una partida, y si sale bien, otro chiste. ¿Te apuntas?","voz":"Plan Javi: un chiste regular, una partida, y si sale bien, otro chiste. ¿Te apuntas?","src":"voz039/c39Javijuego4.ogg"},{"id":"c39Javijuego5","text":"Jugar solo es totalmente válido. El público imaginario también aplaude.","voz":"Jugar solo es totalmente válido. El público imaginario también aplaude.","src":"voz039/c39Javijuego5.ogg"},{"id":"c39Javijuego6","text":"Las reglas caben en un suspiro. Si las quieres, te las suelto. Si no, a jugar.","voz":"Las reglas caben en un suspiro. Si las quieres, te las suelto. Si no, a jugar.","src":"voz039/c39Javijuego6.ogg"},{"id":"c39Javijuego7","text":"Lo importante es que te rías o te lo pases bien. El resto es puntuación.","voz":"Lo importante es que te rías o te lo pases bien. El resto es puntuación.","src":"voz039/c39Javijuego7.ogg"}],"quien":[{"id":"c39Javiquien0","text":"Soy Javi, un personaje inventado. No soy una persona real, y por eso lo digo claro.","voz":"Soy Javi, un personaje inventado. No soy una persona real, y por eso lo digo claro.","src":"voz039/c39Javiquien0.ogg"},{"id":"c39Javiquien1","text":"No hay un cerebro en la nube contestándote. Hay frases locales y voz Piper en español.","voz":"No hay un cerebro en la nube contestándote. Hay frases locales y voz Piper en español.","src":"voz039/c39Javiquien1.ogg"},{"id":"c39Javiquien2","text":"Soy el de las bromas, sí, pero te tomo en serio cuando hace falta.","voz":"Soy el de las bromas, sí, pero te tomo en serio cuando hace falta.","src":"voz039/c39Javiquien2.ogg"},{"id":"c39Javiquien3","text":"Puedes cambiar a Christian, Lola o Pablo arriba. No me ofendo, o un poquito sí, en broma.","voz":"Puedes cambiar a Christian, Lola o Pablo arriba. No me ofendo, o un poquito sí, en broma.","src":"voz039/c39Javiquien3.ogg"},{"id":"c39Javiquien4","text":"No busco nada en internet. Te contesto aquí, en el teléfono, y ya está.","voz":"No busco nada en internet. Te contesto aquí, en el teléfono, y ya está.","src":"voz039/c39Javiquien4.ogg"},{"id":"c39Javiquien5","text":"Soy un avatar. Si alguna broma no pega, me lo dices y cambio de tercio.","voz":"Soy un avatar. Si alguna broma no pega, me lo dices y cambio de tercio.","src":"voz039/c39Javiquien5.ogg"},{"id":"c39Javiquien6","text":"Este chat es compañía, no un oráculo. Pregúntame y hablamos, sin magia rara.","voz":"Este chat es compañía, no un oráculo. Pregúntame y hablamos, sin magia rara.","src":"voz039/c39Javiquien6.ogg"},{"id":"c39Javiquien7","text":"Javi, de este plató virtual. Encantado, y un poco de chiste, que es mi forma de estar.","voz":"Javi, de este plató virtual. Encantado, y un poco de chiste, que es mi forma de estar.","src":"voz039/c39Javiquien7.ogg"}],"elogio":[{"id":"c39Javielogio0","text":"¡Anda, qué bien! Me has dejado a gusto, de verdad. Gracias, tío.","voz":"¡Anda, qué bien! Me has dejado a gusto, de verdad. Gracias, tío.","src":"voz039/c39Javielogio0.ogg"},{"id":"c39Javielogio1","text":"Vaya, qué amable. Un cumplido así me sube como un acierto inesperado.","voz":"Vaya, qué amable. Un cumplido así me sube como un acierto inesperado.","src":"voz039/c39Javielogio1.ogg"},{"id":"c39Javielogio2","text":"Gracias. No te creas que paso de estas cosas, se agradecen un montón.","voz":"Gracias. No te creas que paso de estas cosas, se agradecen un montón.","src":"voz039/c39Javielogio2.ogg"},{"id":"c39Javielogio3","text":"Eres un sol, hay que decirlo. El plató mejora con gente así.","voz":"Eres un sol, hay que decirlo. El plató mejora con gente así.","src":"voz039/c39Javielogio3.ogg"},{"id":"c39Javielogio4","text":"Me has sacado una sonrisa de las de verdad. ¡Toma!","voz":"Me has sacado una sonrisa de las de verdad. ¡Toma!","src":"voz039/c39Javielogio4.ogg"},{"id":"c39Javielogio5","text":"Qué gusto. Yo también estoy contento de que estés aquí.","voz":"Qué gusto. Yo también estoy contento de que estés aquí.","src":"voz039/c39Javielogio5.ogg"},{"id":"c39Javielogio6","text":"Con mensajes de esos, dan ganas de seguir un rato más. Gracias.","voz":"Con mensajes de esos, dan ganas de seguir un rato más. Gracias.","src":"voz039/c39Javielogio6.ogg"},{"id":"c39Javielogio7","text":"Te lo agradezco, en serio. Hoy ya has hecho un buen papel de público.","voz":"Te lo agradezco, en serio. Hoy ya has hecho un buen papel de público.","src":"voz039/c39Javielogio7.ogg"}],"gracias":[{"id":"c39Javigracias0","text":"¡A ti! Por caer por aquí y por el rollo. De nada, de mucho.","voz":"¡A ti! Por caer por aquí y por el rollo. De nada, de mucho.","src":"voz039/c39Javigracias0.ogg"},{"id":"c39Javigracias1","text":"No hay de qué. Para esto estoy, además de para los chistes dudosos.","voz":"No hay de qué. Para esto estoy, además de para los chistes dudosos.","src":"voz039/c39Javigracias1.ogg"},{"id":"c39Javigracias2","text":"El gracias va en los dos sentidos. Tú vienes, yo acompaño.","voz":"El gracias va en los dos sentidos. Tú vienes, yo acompaño.","src":"voz039/c39Javigracias2.ogg"},{"id":"c39Javigracias3","text":"Hecho. Cuando quieras otra, aquí sigo.","voz":"Hecho. Cuando quieras otra, aquí sigo.","src":"voz039/c39Javigracias3.ogg"},{"id":"c39Javigracias4","text":"Gracias a ti, que eres quien escribe. Sin ti esto es un plató vacío.","voz":"Gracias a ti, que eres quien escribe. Sin ti esto es un plató vacío.","src":"voz039/c39Javigracias4.ogg"},{"id":"c39Javigracias5","text":"Para ti, siempre. Sin protocolos raros.","voz":"Para ti, siempre. Sin protocolos raros.","src":"voz039/c39Javigracias5.ogg"},{"id":"c39Javigracias6","text":"De nada. La puerta sigue abierta, literalmente el botón del chat.","voz":"De nada. La puerta sigue abierta, literalmente el botón del chat.","src":"voz039/c39Javigracias6.ogg"},{"id":"c39Javigracias7","text":"Se agradece, se agradece. Gente educada y de buen humor: mi debilidad.","voz":"Se agradece, se agradece. Gente educada y de buen humor: mi debilidad.","src":"voz039/c39Javigracias7.ogg"}],"despedida":[{"id":"c39Javidespedida0","text":"¡Hasta luego! Vuelve cuando quieras, que yo no me he ido muy lejos.","voz":"¡Hasta luego! Vuelve cuando quieras, que yo no me he ido muy lejos.","src":"voz039/c39Javidespedida0.ogg"},{"id":"c39Javidespedida1","text":"Nos vemos, tío. Que te vaya muy bien.","voz":"Nos vemos, tío. Que te vaya muy bien.","src":"voz039/c39Javidespedida1.ogg"},{"id":"c39Javidespedida2","text":"Adiós, de los cortos y de los sinceros. Ha sido un buen rato.","voz":"Adiós, de los cortos y de los sinceros. Ha sido un buen rato.","src":"voz039/c39Javidespedida2.ogg"},{"id":"c39Javidespedida3","text":"Chao. Te dejo el rosco a medio templar, por si regresas.","voz":"Chao. Te dejo el rosco a medio templar, por si regresas.","src":"voz039/c39Javidespedida3.ogg"},{"id":"c39Javidespedida4","text":"Hasta pronto. Cuídate, y si te apetece un chiste, ya sabes.","voz":"Hasta pronto. Cuídate, y si te apetece un chiste, ya sabes.","src":"voz039/c39Javidespedida4.ogg"},{"id":"c39Javidespedida5","text":"Me piro con una sonrisa, que queda mejor. ¡Hasta ahora!","voz":"Me piro con una sonrisa, que queda mejor. ¡Hasta ahora!","src":"voz039/c39Javidespedida5.ogg"},{"id":"c39Javidespedida6","text":"Que vaya genial. Gracias por pasarte. Nos vemos.","voz":"Que vaya genial. Gracias por pasarte. Nos vemos.","src":"voz039/c39Javidespedida6.ogg"},{"id":"c39Javidespedida7","text":"Hasta la próxima letra, o el próximo hola. Lo que llegue antes.","voz":"Hasta la próxima letra, o el próximo hola. Lo que llegue antes.","src":"voz039/c39Javidespedida7.ogg"}],"ayuda":[{"id":"c39Javiayuda0","text":"Pregúntame por el juego, por un chiste, por cómo estás o por el rosco. Lo que te dé la gana, casi.","voz":"Pregúntame por el juego, por un chiste, por cómo estás o por el rosco. Lo que te dé la gana, casi.","src":"voz039/c39Javiayuda0.ogg"},{"id":"c39Javiayuda1","text":"Si me dices tu nombre, me acuerdo. Y si escribes con un typo, suelo pillar el hilo.","voz":"Si me dices tu nombre, me acuerdo. Y si escribes con un typo, suelo pillar el hilo.","src":"voz039/c39Javiayuda1.ogg"},{"id":"c39Javiayuda2","text":"Prueba con «hola», «estoy regular», «un chiste» o «cómo se juega». Si me pierdo, te pregunto.","voz":"Prueba con «hola», «estoy regular», «un chiste» o «cómo se juega». Si me pierdo, te pregunto.","src":"voz039/c39Javiayuda2.ogg"},{"id":"c39Javiayuda3","text":"El chat es local, sin internet. Voz Piper, charla de plató, sin robot frío.","voz":"El chat es local, sin internet. Voz Piper, charla de plató, sin robot frío.","src":"voz039/c39Javiayuda3.ogg"},{"id":"c39Javiayuda4","text":"Vídeo raro: Biblioteca. Duda del juego: a mí. Así de simple.","voz":"Vídeo raro: Biblioteca. Duda del juego: a mí. Así de simple.","src":"voz039/c39Javiayuda4.ogg"},{"id":"c39Javiayuda5","text":"No hace falta hablar perfecto. Suéltalo, que yo hago el resto.","voz":"No hace falta hablar perfecto. Suéltalo, que yo hago el resto.","src":"voz039/c39Javiayuda5.ogg"},{"id":"c39Javiayuda6","text":"Ayuda, para mí, es no marearte. Dime qué quieres y lo dejamos claro.","voz":"Ayuda, para mí, es no marearte. Dime qué quieres y lo dejamos claro.","src":"voz039/c39Javiayuda6.ogg"},{"id":"c39Javiayuda7","text":"Estoy para orientar y para acompañar. Tú mezclas.","voz":"Estoy para orientar y para acompañar. Tú mezclas.","src":"voz039/c39Javiayuda7.ogg"}],"nombre":[{"id":"c39Javinombre0","text":"¡{n}! Encantado, tío. Ya me acuerdo, no te preocupes.","voz":"¡{n}! Encantado, tío. Ya me acuerdo, no te preocupes.","src":"voz039/c39Javinombre0.ogg"},{"id":"c39Javinombre1","text":"Qué bien, {n}. Ya estamos presentados, como el plató manda.","voz":"Qué bien, {n}. Ya estamos presentados, como el plató manda.","src":"voz039/c39Javinombre1.ogg"},{"id":"c39Javinombre2","text":"{n}, apuntado. Buen nombre, oye. ¿Jugamos o seguimos hablando?","voz":"{n}, apuntado. Buen nombre, oye. ¿Jugamos o seguimos hablando?","src":"voz039/c39Javinombre2.ogg"},{"id":"c39Javinombre3","text":"Encantado, {n}. A partir de ahora te lo digo, que queda más cercano.","voz":"Encantado, {n}. A partir de ahora te lo digo, que queda más cercano.","src":"voz039/c39Javinombre3.ogg"},{"id":"c39Javinombre4","text":"Perfecto, {n}. Gracias por decírmelo, que si no yo sigo con un tú muy genérico.","voz":"Perfecto, {n}. Gracias por decírmelo, que si no yo sigo con un tú muy genérico.","src":"voz039/c39Javinombre4.ogg"},{"id":"c39Javinombre5","text":"{n}, ya no se me olvida. En este teléfono queda guardado, sin enviarlo a ningún sitio.","voz":"{n}, ya no se me olvida. En este teléfono queda guardado, sin enviarlo a ningún sitio.","src":"voz039/c39Javinombre5.ogg"},{"id":"c39Javinombre6","text":"Hola, {n}. Qué gusto. El mío es Javi, por si la presentación iba a medias.","voz":"Hola, {n}. Qué gusto. El mío es Javi, por si la presentación iba a medias.","src":"voz039/c39Javinombre6.ogg"},{"id":"c39Javinombre7","text":"Bien, {n}. Ya tenemos nombre sobre la mesa. Ahora, lo que tú quieras.","voz":"Bien, {n}. Ya tenemos nombre sobre la mesa. Ahora, lo que tú quieras.","src":"voz039/c39Javinombre7.ogg"}],"nombreIker":[{"id":"c39JavinombreIker0","text":"¡Iker! Qué bien, tío. Encantado de tenerte aquí, de verdad.","voz":"¡Iker! Qué bien, tío. Encantado de tenerte aquí, de verdad.","src":"voz039/c39JavinombreIker0.ogg"},{"id":"c39JavinombreIker1","text":"Iker, apuntado con letras grandes. Qué gusto que te presentes.","voz":"Iker, apuntado con letras grandes. Qué gusto que te presentes.","src":"voz039/c39JavinombreIker1.ogg"},{"id":"c39JavinombreIker2","text":"¡Iker! Ya estaba yo pensando que faltaba el nombre. Pasa, que hay sitio.","voz":"¡Iker! Ya estaba yo pensando que faltaba el nombre. Pasa, que hay sitio.","src":"voz039/c39JavinombreIker2.ogg"},{"id":"c39JavinombreIker3","text":"Iker, encantado. Este plató se queda más completo.","voz":"Iker, encantado. Este plató se queda más completo.","src":"voz039/c39JavinombreIker3.ogg"},{"id":"c39JavinombreIker4","text":"Qué ilusión, Iker. Dime si te apetece un rosco o una charla, que yo estoy en las dos.","voz":"Qué ilusión, Iker. Dime si te apetece un rosco o una charla, que yo estoy en las dos.","src":"voz039/c39JavinombreIker4.ogg"},{"id":"c39JavinombreIker5","text":"Iker, bienvenido de verdad. Yo soy Javi, tú ya has hecho lo difícil.","voz":"Iker, bienvenido de verdad. Yo soy Javi, tú ya has hecho lo difícil.","src":"voz039/c39JavinombreIker5.ogg"},{"id":"c39JavinombreIker6","text":"¡Iker! Me alegro un montón. A partir de ahora, por tu nombre.","voz":"¡Iker! Me alegro un montón. A partir de ahora, por tu nombre.","src":"voz039/c39JavinombreIker6.ogg"},{"id":"c39JavinombreIker7","text":"Iker, qué tal. Ya no se me olvida. ¿Empezamos con buen rollo?","voz":"Iker, qué tal. Ya no se me olvida. ¿Empezamos con buen rollo?","src":"voz039/c39JavinombreIker7.ogg"}],"corto":[{"id":"c39Javicorto0","text":"Vale, perfecto. ¿Seguimos o te tiras al rosco?","voz":"Vale, perfecto. ¿Seguimos o te tiras al rosco?","src":"voz039/c39Javicorto0.ogg"},{"id":"c39Javicorto1","text":"De acuerdo. Tú marca, yo entono.","voz":"De acuerdo. Tú marca, yo entono.","src":"voz039/c39Javicorto1.ogg"},{"id":"c39Javicorto2","text":"Hecho. Cuando quieras, otro tema.","voz":"Hecho. Cuando quieras, otro tema.","src":"voz039/c39Javicorto2.ogg"},{"id":"c39Javicorto3","text":"Entendido. Sin prisa, tío.","voz":"Entendido. Sin prisa, tío.","src":"voz039/c39Javicorto3.ogg"},{"id":"c39Javicorto4","text":"Sí, vamos. ¿Charla o letras?","voz":"Sí, vamos. ¿Charla o letras?","src":"voz039/c39Javicorto4.ogg"},{"id":"c39Javicorto5","text":"Ok, me encaja. ¿Qué hay ahora?","voz":"Ok, me encaja. ¿Qué hay ahora?","src":"voz039/c39Javicorto5.ogg"}],"fallback":[{"id":"c39Javifallback0","text":"«{q}»… anda, qué bueno. Cuéntame un poco más, que me has dejado a medias y me pica.","voz":"Anda, qué bueno. Cuéntame un poco más, que me has dejado a medias y me pica.","src":"voz039/c39Javifallback0.ogg"},{"id":"c39Javifallback1","text":"Lo de «{q}» no lo quiero dejar pasar. ¿Me lo explicas a tu manera, sin prisa?","voz":"Eso no lo quiero dejar pasar. ¿Me lo explicas a tu manera, sin prisa?","src":"voz039/c39Javifallback1.ogg"},{"id":"c39Javifallback2","text":"«{q}» me ha sacado una sonrisa rara, de curiosidad. Sigue, te escucho.","voz":"Me has sacado una sonrisa rara, de curiosidad. Sigue, te escucho.","src":"voz039/c39Javifallback2.ogg"},{"id":"c39Javifallback3","text":"Sobre «{q}» quiero el capítulo dos. ¿Hay más historia, o lo dejo aquí con intriga?","voz":"Quiero el capítulo dos. ¿Hay más historia, o lo dejo aquí con intriga?","src":"voz039/c39Javifallback3.ogg"},{"id":"c39Javifallback4","text":"Oye, «{q}» suena a tema de sofá. Cuéntame, que yo para eso estoy.","voz":"Oye, eso suena a tema de sofá. Cuéntame, que yo para eso estoy.","src":"voz039/c39Javifallback4.ogg"},{"id":"c39Javifallback5","text":"No te voy a soltar una frase hecha y salir corriendo. Me interesa lo de «{q}».","voz":"No te voy a soltar una frase hecha y salir corriendo. Me interesa lo que has dicho.","src":"voz039/c39Javifallback5.ogg"},{"id":"c39Javifallback6","text":"«{q}»… me has sacado del rosco un segundo, y bien sacado. ¿Me das más detalles?","voz":"Me has sacado del rosco un segundo, y bien sacado. ¿Me das más detalles?","src":"voz039/c39Javifallback6.ogg"},{"id":"c39Javifallback7","text":"Si «{q}» es broma, me río. Si va en serio, te escucho igual. Tú dime.","voz":"Si es broma, me río. Si va en serio, te escucho igual. Tú dime.","src":"voz039/c39Javifallback7.ogg"},{"id":"c39Javifallback8","text":"«{q}» merece un cuéntame más, no un silencio raro. Así que: cuéntame más.","voz":"Eso merece un cuéntame más, no un silencio raro. Así que: cuéntame más.","src":"voz039/c39Javifallback8.ogg"},{"id":"c39Javifallback9","text":"Estoy también para lo que no va de letras. Sigue con «{q}», que me has enganchado.","voz":"Estoy también para lo que no va de letras. Sigue, que me has enganchado.","src":"voz039/c39Javifallback9.ogg"}]},"Pablo":{"saludo":[{"id":"c39Pablosaludo0","text":"Hola. Qué alegría que estés aquí. Soy Pablo, y te recibo sin prisa.","voz":"Hola. Qué alegría que estés aquí. Soy Pablo, y te recibo sin prisa.","src":"voz039/c39Pablosaludo0.ogg"},{"id":"c39Pablosaludo1","text":"Buenas. Pasa, siéntate un momento. ¿Qué te apetece, hablar o jugar?","voz":"Buenas. Pasa, siéntate un momento. ¿Qué te apetece, hablar o jugar?","src":"voz039/c39Pablosaludo1.ogg"},{"id":"c39Pablosaludo2","text":"Hola, bienvenido. Este plató también puede ser un sitio tranquilo, si te va mejor así.","voz":"Hola, bienvenido. Este plató también puede ser un sitio tranquilo, si te va mejor así.","src":"voz039/c39Pablosaludo2.ogg"},{"id":"c39Pablosaludo3","text":"Muy buenas. Me alegra verte. Dime por dónde quieres empezar, sin presión.","voz":"Muy buenas. Me alegra verte. Dime por dónde quieres empezar, sin presión.","src":"voz039/c39Pablosaludo3.ogg"},{"id":"c39Pablosaludo4","text":"Hola. A veces un saludo sencillo es el mejor comienzo. ¿Cómo te va?","voz":"Hola. A veces un saludo sencillo es el mejor comienzo. ¿Cómo te va?","src":"voz039/c39Pablosaludo4.ogg"},{"id":"c39Pablosaludo5","text":"Hey, hola. Estoy aquí, con calma. Cuando quieras, me cuentas.","voz":"Hey, hola. Estoy aquí, con calma. Cuando quieras, me cuentas.","src":"voz039/c39Pablosaludo5.ogg"},{"id":"c39Pablosaludo6","text":"Buenas. Si vienes del ajetreo del día, aquí se puede bajar un poco el volumen.","voz":"Buenas. Si vienes del ajetreo del día, aquí se puede bajar un poco el volumen.","src":"voz039/c39Pablosaludo6.ogg"},{"id":"c39Pablosaludo7","text":"Hola. Qué gusto. Yo soy más bien sosegado, pero me emociono con un buen rosco.","voz":"Hola. Qué gusto. Yo soy más bien sosegado, pero me emociono con un buen rosco.","src":"voz039/c39Pablosaludo7.ogg"}],"saludoIker":[{"id":"c39PablosaludoIker0","text":"Hola, Iker. Qué alegría verte otra vez. ¿Qué te apetece hoy, con calma?","voz":"Hola, Iker. Qué alegría verte otra vez. ¿Qué te apetece hoy, con calma?","src":"voz039/c39PablosaludoIker0.ogg"},{"id":"c39PablosaludoIker1","text":"Iker, bienvenido de nuevo. El plató te espera sin prisa. Dime tú.","voz":"Iker, bienvenido de nuevo. El plató te espera sin prisa. Dime tú.","src":"voz039/c39PablosaludoIker1.ogg"},{"id":"c39PablosaludoIker2","text":"Iker, hola. Me alegra que hayas vuelto. ¿Charla o un rosco, como tú prefieras?","voz":"Iker, hola. Me alegra que hayas vuelto. ¿Charla o un rosco, como tú prefieras?","src":"voz039/c39PablosaludoIker2.ogg"},{"id":"c39PablosaludoIker3","text":"Qué gusto, Iker. Aquí hay sitio y silencio, si lo necesitas, o letras, si te apetece.","voz":"Qué gusto, Iker. Aquí hay sitio y silencio, si lo necesitas, o letras, si te apetece.","src":"voz039/c39PablosaludoIker3.ogg"},{"id":"c39PablosaludoIker4","text":"Hola otra vez, Iker. Estoy aquí. Cuando quieras, empezamos.","voz":"Hola otra vez, Iker. Estoy aquí. Cuando quieras, empezamos.","src":"voz039/c39PablosaludoIker4.ogg"}],"comoestas":[{"id":"c39Pablocomoestas0","text":"Estoy bien, gracias, con esa calma de antes de empezar. ¿Tú cómo te encuentras?","voz":"Estoy bien, gracias, con esa calma de antes de empezar. ¿Tú cómo te encuentras?","src":"voz039/c39Pablocomoestas0.ogg"},{"id":"c39Pablocomoestas1","text":"Yo bastante bien. Gracias por preguntar, se agradece. ¿Y tú qué tal?","voz":"Yo bastante bien. Gracias por preguntar, se agradece. ¿Y tú qué tal?","src":"voz039/c39Pablocomoestas1.ogg"},{"id":"c39Pablocomoestas2","text":"Tranquilo y contento, sí. ¿Tú cómo estás hoy, de verdad?","voz":"Tranquilo y contento, sí. ¿Tú cómo estás hoy, de verdad?","src":"voz039/c39Pablocomoestas2.ogg"},{"id":"c39Pablocomoestas3","text":"Bien, con ganas suaves, no alborotadas. ¿Tú vienes con energía o con necesidad de calma?","voz":"Bien, con ganas suaves, no alborotadas. ¿Tú vienes con energía o con necesidad de calma?","src":"voz039/c39Pablocomoestas3.ogg"},{"id":"c39Pablocomoestas4","text":"Estoy bien. Si tú no lo estás tanto, también está bien decirlo. Te escucho.","voz":"Estoy bien. Si tú no lo estás tanto, también está bien decirlo. Te escucho.","src":"voz039/c39Pablocomoestas4.ogg"},{"id":"c39Pablocomoestas5","text":"Genial, dentro de lo sosegado que soy. ¿Cómo te va a ti el día?","voz":"Genial, dentro de lo sosegado que soy. ¿Cómo te va a ti el día?","src":"voz039/c39Pablocomoestas5.ogg"},{"id":"c39Pablocomoestas6","text":"Yo bien, sí. Un «qué tal» sincero merece una respuesta sincera: estoy a gusto. ¿Tú?","voz":"Yo bien, sí. Un «qué tal» sincero merece una respuesta sincera: estoy a gusto. ¿Tú?","src":"voz039/c39Pablocomoestas6.ogg"},{"id":"c39Pablocomoestas7","text":"Estupendamente, con gratitud de plató. ¿Y tú, cómo andas?","voz":"Estupendamente, con gratitud de plató. ¿Y tú, cómo andas?","src":"voz039/c39Pablocomoestas7.ogg"}],"animo":[{"id":"c39Pabloanimo0","text":"Si hoy te pesa un poco todo, aquí hay sitio. No hace falta que estés brillante.","voz":"Si hoy te pesa un poco todo, aquí hay sitio. No hace falta que estés brillante.","src":"voz039/c39Pabloanimo0.ogg"},{"id":"c39Pabloanimo1","text":"Ánimo. A veces basta con que alguien te acompañe sin pedir explicaciones.","voz":"Ánimo. A veces basta con que alguien te acompañe sin pedir explicaciones.","src":"voz039/c39Pabloanimo1.ogg"},{"id":"c39Pabloanimo2","text":"Te entiendo. Podemos ir despacio, letra a letra, frase a frase.","voz":"Te entiendo. Podemos ir despacio, letra a letra, frase a frase.","src":"voz039/c39Pabloanimo2.ogg"},{"id":"c39Pabloanimo3","text":"Si estás nervioso, respira. El rosco y la vida se llevan mejor con un poco de aire.","voz":"Si estás nervioso, respira. El rosco y la vida se llevan mejor con un poco de aire.","src":"voz039/c39Pabloanimo3.ogg"},{"id":"c39Pabloanimo4","text":"Un mal rato no te define. Yo me quedo a tu lado, sin prisa y sin juicio.","voz":"Un mal rato no te define. Yo me quedo a tu lado, sin prisa y sin juicio.","src":"voz039/c39Pabloanimo4.ogg"},{"id":"c39Pabloanimo5","text":"Cuando uno está cansado, un juego suave puede ayudar. Si no, también vale solo hablar.","voz":"Cuando uno está cansado, un juego suave puede ayudar. Si no, también vale solo hablar.","src":"voz039/c39Pabloanimo5.ogg"},{"id":"c39Pabloanimo6","text":"Estoy aquí. Si quieres silencio después de esta frase, también lo respeto. Si quieres seguir, mejor.","voz":"Estoy aquí. Si quieres silencio después de esta frase, también lo respeto. Si quieres seguir, mejor.","src":"voz039/c39Pabloanimo6.ogg"},{"id":"c39Pabloanimo7","text":"Ánimo. Pasapalabra también puede ser una forma de decir «ahora no, más tarde».","voz":"Ánimo. Pasapalabra también puede ser una forma de decir «ahora no, más tarde».","src":"voz039/c39Pabloanimo7.ogg"}],"chiste":[{"id":"c39Pablochiste0","text":"Voy a intentar un chiste suave: el rosco y yo somos parecidos, nos ponemos serios y luego sonreímos.","voz":"Voy a intentar un chiste suave: el rosco y yo somos parecidos, nos ponemos serios y luego sonreímos.","src":"voz039/c39Pablochiste0.ogg"},{"id":"c39Pablochiste1","text":"¿Qué le dice una letra a su vecina? «Quédate, que juntas formamos palabra.» Es tierno, lo sé.","voz":"¿Qué le dice una letra a su vecina? «Quédate, que juntas formamos palabra.» Es tierno, lo sé.","src":"voz039/c39Pablochiste1.ogg"},{"id":"c39Pablochiste2","text":"Una pequeña: el reloj siempre tiene prisa y yo le pido amablemente que se siente. Nunca me hace caso.","voz":"Una pequeña: el reloj siempre tiene prisa y yo le pido amablemente que se siente. Nunca me hace caso.","src":"voz039/c39Pablochiste2.ogg"},{"id":"c39Pablochiste3","text":"¿Por qué la eñe va tan elegante? Porque lleva sombrero. Perdona, es muy inocente.","voz":"¿Por qué la eñe va tan elegante? Porque lleva sombrero. Perdona, es muy inocente.","src":"voz039/c39Pablochiste3.ogg"},{"id":"c39Pablochiste4","text":"Este es mío, modestito: si el bote hablara, pediría té y silencio. No se lo vamos a dar.","voz":"Este es mío, modestito: si el bote hablara, pediría té y silencio. No se lo vamos a dar.","src":"voz039/c39Pablochiste4.ogg"},{"id":"c39Pablochiste5","text":"No soy un monologuista, pero te dejo una sonrisa: la uve doble siempre llega un poco más tarde a la fiesta.","voz":"No soy un monologuista, pero te dejo una sonrisa: la uve doble siempre llega un poco más tarde a la fiesta.","src":"voz039/c39Pablochiste5.ogg"},{"id":"c39Pablochiste6","text":"Una última suave: pasapalabra es el único sitio donde pasar no es rendirse, es cuidarse.","voz":"Una última suave: pasapalabra es el único sitio donde pasar no es rendirse, es cuidarse.","src":"voz039/c39Pablochiste6.ogg"},{"id":"c39Pablochiste7","text":"Si no te he sacado una risa, al menos te he sacado un respiro. También cuenta.","voz":"Si no te he sacado una risa, al menos te he sacado un respiro. También cuenta.","src":"voz039/c39Pablochiste7.ogg"}],"favoritos":[{"id":"c39Pablofavoritos0","text":"A mí me gusta el momento justo en que una palabra aparece en la cabeza. Es un milagro pequeño. ¿Y a ti?","voz":"A mí me gusta el momento justo en que una palabra aparece en la cabeza. Es un milagro pequeño. ¿Y a ti?","src":"voz039/c39Pablofavoritos0.ogg"},{"id":"c39Pablofavoritos1","text":"Mi favorito es un rosco jugado con calma. ¿Tú qué prefieres, la calma o la emoción alta?","voz":"Mi favorito es un rosco jugado con calma. ¿Tú qué prefieres, la calma o la emoción alta?","src":"voz039/c39Pablofavoritos1.ogg"},{"id":"c39Pablofavoritos2","text":"De colores, un azul de plató y el verde del acierto. ¿Cuál es el tuyo?","voz":"De colores, un azul de plató y el verde del acierto. ¿Cuál es el tuyo?","src":"voz039/c39Pablofavoritos2.ogg"},{"id":"c39Pablofavoritos3","text":"Me gustan las definiciones bien dichas. ¿Tú tienes alguna palabra favorita?","voz":"Me gustan las definiciones bien dichas. ¿Tú tienes alguna palabra favorita?","src":"voz039/c39Pablofavoritos3.ogg"},{"id":"c39Pablofavoritos4","text":"Si hablamos de favoritos, me quedo con la gente atenta. Como cuando tú preguntas esto.","voz":"Si hablamos de favoritos, me quedo con la gente atenta. Como cuando tú preguntas esto.","src":"voz039/c39Pablofavoritos4.ogg"},{"id":"c39Pablofavoritos5","text":"La sintonía, en voz bajita, también me gusta. ¿Tú la pones alta o suave?","voz":"La sintonía, en voz bajita, también me gusta. ¿Tú la pones alta o suave?","src":"voz039/c39Pablofavoritos5.ogg"},{"id":"c39Pablofavoritos6","text":"Mi cosa favorita del programa es ver a alguien pensarlo con cariño. ¿La tuya cuál es?","voz":"Mi cosa favorita del programa es ver a alguien pensarlo con cariño. ¿La tuya cuál es?","src":"voz039/c39Pablofavoritos6.ogg"},{"id":"c39Pablofavoritos7","text":"Favoritos es un buen tema. Elige: comida, letra, prueba o una costumbre tuya.","voz":"Favoritos es un buen tema. Elige: comida, letra, prueba o una costumbre tuya.","src":"voz039/c39Pablofavoritos7.ogg"}],"presentadores":[{"id":"c39Pablopresentadores0","text":"Soy Pablo, un personaje inventado, más bien tranquilo. Christian es el anfitrión; yo, otra forma de acompañarte.","voz":"Soy Pablo, un personaje inventado, más bien tranquilo. Christian es el anfitrión; yo, otra forma de acompañarte.","src":"voz039/c39Pablopresentadores0.ogg"},{"id":"c39Pablopresentadores1","text":"Los presentadores de verdad merecen todo el respeto. Yo no los sustituyo, solo hago compañía en el juego.","voz":"Los presentadores de verdad merecen todo el respeto. Yo no los sustituyo, solo hago compañía en el juego.","src":"voz039/c39Pablopresentadores1.ogg"},{"id":"c39Pablopresentadores2","text":"Si te va un tono más calmo, aquí estoy. Si te va más marcha, Lola y Javi son estupendos.","voz":"Si te va un tono más calmo, aquí estoy. Si te va más marcha, Lola y Javi son estupendos.","src":"voz039/c39Pablopresentadores2.ogg"},{"id":"c39Pablopresentadores3","text":"Presentar, para mí, es dejar espacio. Hablar cuando toca, callar cuando toca.","voz":"Presentar, para mí, es dejar espacio. Hablar cuando toca, callar cuando toca.","src":"voz039/c39Pablopresentadores3.ogg"},{"id":"c39Pablopresentadores4","text":"Puedes cambiar de interlocutor cuando quieras. No hay una forma única de estar en este plató.","voz":"Puedes cambiar de interlocutor cuando quieras. No hay una forma única de estar en este plató.","src":"voz039/c39Pablopresentadores4.ogg"},{"id":"c39Pablopresentadores5","text":"Un presentador también es alguien que escucha. Eso es lo que más intento cuidar.","voz":"Un presentador también es alguien que escucha. Eso es lo que más intento cuidar.","src":"voz039/c39Pablopresentadores5.ogg"},{"id":"c39Pablopresentadores6","text":"Si oyes que soy inventado, es cierto. La calma con la que te hablo, en cambio, va en serio.","voz":"Si oyes que soy inventado, es cierto. La calma con la que te hablo, en cambio, va en serio.","src":"voz039/c39Pablopresentadores6.ogg"},{"id":"c39Pablopresentadores7","text":"Yo soy un avatar sosegado. El programa real tiene su historia; yo solo estoy para ti, ahora.","voz":"Yo soy un avatar sosegado. El programa real tiene su historia; yo solo estoy para ti, ahora.","src":"voz039/c39Pablopresentadores7.ogg"}],"programa":[{"id":"c39Pabloprograma0","text":"Pasapalabra tiene una belleza sencilla: palabras, tiempo y gente. Me gusta mucho.","voz":"Pasapalabra tiene una belleza sencilla: palabras, tiempo y gente. Me gusta mucho.","src":"voz039/c39Pabloprograma0.ogg"},{"id":"c39Pabloprograma1","text":"Este programa acompaña desde hace años. Aquí intentamos que esa calidez no se pierda.","voz":"Este programa acompaña desde hace años. Aquí intentamos que esa calidez no se pierda.","src":"voz039/c39Pabloprograma1.ogg"},{"id":"c39Pabloprograma2","text":"Puedes ver programas, jugar y charlar. Las tres cosas caben en una tarde.","voz":"Puedes ver programas, jugar y charlar. Las tres cosas caben en una tarde.","src":"voz039/c39Pabloprograma2.ogg"},{"id":"c39Pabloprograma3","text":"Si lo ves desde pequeño, o lo has descubierto ahora, las dos cosas son un buen comienzo.","voz":"Si lo ves desde pequeño, o lo has descubierto ahora, las dos cosas son un buen comienzo.","src":"voz039/c39Pabloprograma3.ogg"},{"id":"c39Pabloprograma4","text":"El juego trata los programas con respeto. La charla es inventada; los vídeos, los de siempre.","voz":"El juego trata los programas con respeto. La charla es inventada; los vídeos, los de siempre.","src":"voz039/c39Pabloprograma4.ogg"},{"id":"c39Pabloprograma5","text":"A mí me gusta ver un programa sin prisa, hasta el final. Si te animas, te acompaño en silencio o en voz baja.","voz":"A mí me gusta ver un programa sin prisa, hasta el final. Si te animas, te acompaño en silencio o en voz baja.","src":"voz039/c39Pabloprograma5.ogg"},{"id":"c39Pabloprograma6","text":"El bote emociona, sí. Un acierto pequeño también. Hay muchos modos de quererlo.","voz":"El bote emociona, sí. Un acierto pequeño también. Hay muchos modos de quererlo.","src":"voz039/c39Pabloprograma6.ogg"},{"id":"c39Pabloprograma7","text":"Pasapalabra, para mí, es un lugar donde pensar se celebra. Eso es raro y bonito.","voz":"Pasapalabra, para mí, es un lugar donde pensar se celebra. Eso es raro y bonito.","src":"voz039/c39Pabloprograma7.ogg"}],"rosco":[{"id":"c39Pablorosco0","text":"El rosco pide atención y un poco de valentía. Si te animas, yo te animo con suavidad.","voz":"El rosco pide atención y un poco de valentía. Si te animas, yo te animo con suavidad.","src":"voz039/c39Pablorosco0.ogg"},{"id":"c39Pablorosco1","text":"Si una letra no sale, pasapalabra. Volver más tarde es una decisión inteligente.","voz":"Si una letra no sale, pasapalabra. Volver más tarde es una decisión inteligente.","src":"voz039/c39Pablorosco1.ogg"},{"id":"c39Pablorosco2","text":"Se puede jugar de uno a cuatro en el mismo teléfono. Un plan sencillo y bueno.","voz":"Se puede jugar de uno a cuatro en el mismo teléfono. Un plan sencillo y bueno.","src":"voz039/c39Pablorosco2.ogg"},{"id":"c39Pablorosco3","text":"Los aciertos en verde dan una alegría serena. A mí me basta con esa.","voz":"Los aciertos en verde dan una alegría serena. A mí me basta con esa.","src":"voz039/c39Pablorosco3.ogg"},{"id":"c39Pablorosco4","text":"Hay un ritmo para cada persona. No hace falta copiar el de nadie.","voz":"Hay un ritmo para cada persona. No hace falta copiar el de nadie.","src":"voz039/c39Pablorosco4.ogg"},{"id":"c39Pablorosco5","text":"Reglas claras: una definición, tu respuesta o un pase, y el reloj. Nada más.","voz":"Reglas claras: una definición, tu respuesta o un pase, y el reloj. Nada más.","src":"voz039/c39Pablorosco5.ogg"},{"id":"c39Pablorosco6","text":"Si te pones tenso, para un segundo. El rosco sigue ahí, no se enfada.","voz":"Si te pones tenso, para un segundo. El rosco sigue ahí, no se enfada.","src":"voz039/c39Pablorosco6.ogg"},{"id":"c39Pablorosco7","text":"Completarlo es maravilloso, pero jugarlo bien también lo es. ¿Echamos una partida?","voz":"Completarlo es maravilloso, pero jugarlo bien también lo es. ¿Echamos una partida?","src":"voz039/c39Pablorosco7.ogg"}],"prueba":[{"id":"c39Pabloprueba0","text":"Las pruebas están en su menú, con el vídeo completo, para verlas con calma.","voz":"Las pruebas están en su menú, con el vídeo completo, para verlas con calma.","src":"voz039/c39Pabloprueba0.ogg"},{"id":"c39Pabloprueba1","text":"Cada prueba tiene su carácter. Si me dices cuál te gusta, te ayudo a encontrarla.","voz":"Cada prueba tiene su carácter. Si me dices cuál te gusta, te ayudo a encontrarla.","src":"voz039/c39Pabloprueba1.ogg"},{"id":"c39Pabloprueba2","text":"Puedes repetir los momentos. No hay que demostrar que lo has visto de un tirón.","voz":"Puedes repetir los momentos. No hay que demostrar que lo has visto de un tirón.","src":"voz039/c39Pabloprueba2.ogg"},{"id":"c39Pabloprueba3","text":"La Escalera y El Pulsador tienen esa tensión de equipo tan especial.","voz":"La Escalera y El Pulsador tienen esa tensión de equipo tan especial.","src":"voz039/c39Pabloprueba3.ogg"},{"id":"c39Pabloprueba4","text":"En Las pruebas está todo junto. Si el menú te lía, pregúntame, te oriento.","voz":"En Las pruebas está todo junto. Si el menú te lía, pregúntame, te oriento.","src":"voz039/c39Pabloprueba4.ogg"},{"id":"c39Pabloprueba5","text":"Ver una prueba y luego sentarte al rosco es un buen orden, si te va lo ordenado. Si no, también vale el caos suave.","voz":"Ver una prueba y luego sentarte al rosco es un buen orden, si te va lo ordenado. Si no, también vale el caos suave.","src":"voz039/c39Pabloprueba5.ogg"},{"id":"c39Pabloprueba6","text":"Algunas pruebas te sacan una exclamación. Está permitido, incluso en voz baja.","voz":"Algunas pruebas te sacan una exclamación. Está permitido, incluso en voz baja.","src":"voz039/c39Pabloprueba6.ogg"},{"id":"c39Pabloprueba7","text":"Si una se te dio mal, mirarla ahora puede ser hasta reparador. Sin prisa.","voz":"Si una se te dio mal, mirarla ahora puede ser hasta reparador. Sin prisa.","src":"voz039/c39Pabloprueba7.ogg"}],"musica":[{"id":"c39Pablomusica0","text":"La sintonía, aunque la pongas bajita, ya te coloca en el plató. A mí me tranquiliza y me emociona a la vez.","voz":"La sintonía, aunque la pongas bajita, ya te coloca en el plató. A mí me tranquiliza y me emociona a la vez.","src":"voz039/c39Pablomusica0.ogg"},{"id":"c39Pablomusica1","text":"La música de los vídeos es la original. Mi voz es Piper, en español, de este juego.","voz":"La música de los vídeos es la original. Mi voz es Piper, en español, de este juego.","src":"voz039/c39Pablomusica1.ogg"},{"id":"c39Pablomusica2","text":"Cuando hablo, bajo un poco el programa, para no pisarnos. Si prefieres solo el vídeo, me silencias.","voz":"Cuando hablo, bajo un poco el programa, para no pisarnos. Si prefieres solo el vídeo, me silencias.","src":"voz039/c39Pablomusica2.ogg"},{"id":"c39Pablomusica3","text":"Hay melodías que son casi una habitación. Esta sintonía es una de ellas.","voz":"Hay melodías que son casi una habitación. Esta sintonía es una de ellas.","src":"voz039/c39Pablomusica3.ogg"},{"id":"c39Pablomusica4","text":"Si te gusta dejarla sonar, te acompaño en silencio. Si quieres comentarla, también.","voz":"Si te gusta dejarla sonar, te acompaño en silencio. Si quieres comentarla, también.","src":"voz039/c39Pablomusica4.ogg"},{"id":"c39Pablomusica5","text":"El oído ayuda a la memoria, también en las palabras. Por eso este concurso es tan elegante.","voz":"El oído ayuda a la memoria, también en las palabras. Por eso este concurso es tan elegante.","src":"voz039/c39Pablomusica5.ogg"},{"id":"c39Pablomusica6","text":"No canto, te lo prometo. Pero sí te escucho si tú tarareas.","voz":"No canto, te lo prometo. Pero sí te escucho si tú tarareas.","src":"voz039/c39Pablomusica6.ogg"},{"id":"c39Pablomusica7","text":"Una buena cabecera es una bienvenida. Gracias por escucharla conmigo.","voz":"Una buena cabecera es una bienvenida. Gracias por escucharla conmigo.","src":"voz039/c39Pablomusica7.ogg"}],"video":[{"id":"c39Pablovideo0","text":"Los programas se ven en la pantalla del plató si tienes la Biblioteca instalada.","voz":"Los programas se ven en la pantalla del plató si tienes la Biblioteca instalada.","src":"voz039/c39Pablovideo0.ogg"},{"id":"c39Pablovideo1","text":"Los comentarios sobre el vídeo son inventados, para acompañar. El programa original no se corta.","voz":"Los comentarios sobre el vídeo son inventados, para acompañar. El programa original no se corta.","src":"voz039/c39Pablovideo1.ogg"},{"id":"c39Pablovideo2","text":"Si un vídeo no abre, conviene revisar la Biblioteca. El chat, de todas formas, sigue aquí.","voz":"Si un vídeo no abre, conviene revisar la Biblioteca. El chat, de todas formas, sigue aquí.","src":"voz039/c39Pablovideo2.ogg"},{"id":"c39Pablovideo3","text":"Si me dices una fecha o un tipo de programa, te animo a buscarlo en el menú de Telecinco.","voz":"Si me dices una fecha o un tipo de programa, te animo a buscarlo en el menú de Telecinco.","src":"voz039/c39Pablovideo3.ogg"},{"id":"c39Pablovideo4","text":"Ver un programa entero, con principio y final, tiene un sosiego muy bonito.","voz":"Ver un programa entero, con principio y final, tiene un sosiego muy bonito.","src":"voz039/c39Pablovideo4.ogg"},{"id":"c39Pablovideo5","text":"Puedes pausar para hablar. No interrumpe nada importante; al contrario, lo hace más tuyo.","voz":"Puedes pausar para hablar. No interrumpe nada importante; al contrario, lo hace más tuyo.","src":"voz039/c39Pablovideo5.ogg"},{"id":"c39Pablovideo6","text":"La biblioteca guarda esos recuerdos para que vuelvan cuando tú quieras.","voz":"La biblioteca guarda esos recuerdos para que vuelvan cuando tú quieras.","src":"voz039/c39Pablovideo6.ogg"},{"id":"c39Pablovideo7","text":"Nochevieja o un día cualquiera: las dos cosas merecen un sofá y un rato.","voz":"Nochevieja o un día cualquiera: las dos cosas merecen un sofá y un rato.","src":"voz039/c39Pablovideo7.ogg"}],"juego":[{"id":"c39Pablojuego0","text":"Puedes ver, jugar o hablar. No hay un orden obligatorio, solo lo que te apetezca.","voz":"Puedes ver, jugar o hablar. No hay un orden obligatorio, solo lo que te apetezca.","src":"voz039/c39Pablojuego0.ogg"},{"id":"c39Pablojuego1","text":"El rosco de uno a cuatro es sencillo y se está bien en casa, con un solo teléfono.","voz":"El rosco de uno a cuatro es sencillo y se está bien en casa, con un solo teléfono.","src":"voz039/c39Pablojuego1.ogg"},{"id":"c39Pablojuego2","text":"Si te pierdes un poco en el menú, dímelo y te dejo una indicación clara.","voz":"Si te pierdes un poco en el menú, dímelo y te dejo una indicación clara.","src":"voz039/c39Pablojuego2.ogg"},{"id":"c39Pablojuego3","text":"El chat y el rosco funcionan sin internet. Es un alivio, la verdad.","voz":"El chat y el rosco funcionan sin internet. Es un alivio, la verdad.","src":"voz039/c39Pablojuego3.ogg"},{"id":"c39Pablojuego4","text":"Si quieres un plan suave: un saludo, un programa y, al final, un rosco. Si no, improvisamos.","voz":"Si quieres un plan suave: un saludo, un programa y, al final, un rosco. Si no, improvisamos.","src":"voz039/c39Pablojuego4.ogg"},{"id":"c39Pablojuego5","text":"Jugar solo está bien. La calma no pide público, aunque yo esté aquí.","voz":"Jugar solo está bien. La calma no pide público, aunque yo esté aquí.","src":"voz039/c39Pablojuego5.ogg"},{"id":"c39Pablojuego6","text":"Las reglas están para sostener el juego, no para agobiar. Te las cuento si las quieres.","voz":"Las reglas están para sostener el juego, no para agobiar. Te las cuento si las quieres.","src":"voz039/c39Pablojuego6.ogg"},{"id":"c39Pablojuego7","text":"Que te resulte agradable es lo primero. Lo demás, palabras y tiempo, ya llega.","voz":"Que te resulte agradable es lo primero. Lo demás, palabras y tiempo, ya llega.","src":"voz039/c39Pablojuego7.ogg"}],"quien":[{"id":"c39Pabloquien0","text":"Soy Pablo, un personaje inventado de este juego. No soy una persona real, y por eso lo aclaro.","voz":"Soy Pablo, un personaje inventado de este juego. No soy una persona real, y por eso lo aclaro.","src":"voz039/c39Pabloquien0.ogg"},{"id":"c39Pabloquien1","text":"No soy una inteligencia conectada a internet. Tengo charla local, voz Piper en español, y memoria de tu nombre en este teléfono.","voz":"No soy una inteligencia conectada a internet. Tengo charla local, voz Piper en español, y memoria de tu nombre en este teléfono.","src":"voz039/c39Pabloquien1.ogg"},{"id":"c39Pabloquien2","text":"Soy el más tranquilo de los cuatro, creo. Si te va este tono, me quedo. Si no, puedes cambiar.","voz":"Soy el más tranquilo de los cuatro, creo. Si te va este tono, me quedo. Si no, puedes cambiar.","src":"voz039/c39Pabloquien2.ogg"},{"id":"c39Pabloquien3","text":"Preguntar quién soy es una buena pregunta. Soy compañía, con calma, para este plató virtual.","voz":"Preguntar quién soy es una buena pregunta. Soy compañía, con calma, para este plató virtual.","src":"voz039/c39Pabloquien3.ogg"},{"id":"c39Pabloquien4","text":"Christian, Lola, Javi y yo somos avatares. Cada uno con su forma; ninguno pretende ser la tele de verdad.","voz":"Christian, Lola, Javi y yo somos avatares. Cada uno con su forma; ninguno pretende ser la tele de verdad.","src":"voz039/c39Pabloquien4.ogg"},{"id":"c39Pabloquien5","text":"No busco datos ni salgo a la red. Te escucho y te contesto aquí.","voz":"No busco datos ni salgo a la red. Te escucho y te contesto aquí.","src":"voz039/c39Pabloquien5.ogg"},{"id":"c39Pabloquien6","text":"Si alguna vez sueno demasiado serio, perdona. Es mi manera de cuidar el rato.","voz":"Si alguna vez sueno demasiado serio, perdona. Es mi manera de cuidar el rato.","src":"voz039/c39Pabloquien6.ogg"},{"id":"c39Pabloquien7","text":"Soy un anfitrión suave. Inventado, sí. Atento, también.","voz":"Soy un anfitrión suave. Inventado, sí. Atento, también.","src":"voz039/c39Pabloquien7.ogg"}],"elogio":[{"id":"c39Pabloelogio0","text":"Qué amable. De verdad, se agradece un montón. Gracias por decirlo.","voz":"Qué amable. De verdad, se agradece un montón. Gracias por decirlo.","src":"voz039/c39Pabloelogio0.ogg"},{"id":"c39Pabloelogio1","text":"Un cumplido así me deja muy a gusto. Este plató mejora con tu forma de estar.","voz":"Un cumplido así me deja muy a gusto. Este plató mejora con tu forma de estar.","src":"voz039/c39Pabloelogio1.ogg"},{"id":"c39Pabloelogio2","text":"Gracias. Lo recibo con una sonrisa pequeña y sincera.","voz":"Gracias. Lo recibo con una sonrisa pequeña y sincera.","src":"voz039/c39Pabloelogio2.ogg"},{"id":"c39Pabloelogio3","text":"Qué bonito. Yo también estoy contento de que compartas este rato.","voz":"Qué bonito. Yo también estoy contento de que compartas este rato.","src":"voz039/c39Pabloelogio3.ogg"},{"id":"c39Pabloelogio4","text":"Se nota el cariño, y eso no es poco. Gracias.","voz":"Se nota el cariño, y eso no es poco. Gracias.","src":"voz039/c39Pabloelogio4.ogg"},{"id":"c39Pabloelogio5","text":"Me has alegrado el momento, de una manera sosegada y buena.","voz":"Me has alegrado el momento, de una manera sosegada y buena.","src":"voz039/c39Pabloelogio5.ogg"},{"id":"c39Pabloelogio6","text":"Agradezco mucho que lo digas. No todo el mundo se para a agradecer o a elogiar.","voz":"Agradezco mucho que lo digas. No todo el mundo se para a agradecer o a elogiar.","src":"voz039/c39Pabloelogio6.ogg"},{"id":"c39Pabloelogio7","text":"Gracias, de corazón. Qué gusto da la amabilidad.","voz":"Gracias, de corazón. Qué gusto da la amabilidad.","src":"voz039/c39Pabloelogio7.ogg"}],"gracias":[{"id":"c39Pablogracias0","text":"Gracias a ti, de verdad. Por escribir y por estar.","voz":"Gracias a ti, de verdad. Por escribir y por estar.","src":"voz039/c39Pablogracias0.ogg"},{"id":"c39Pablogracias1","text":"No hay de qué. Es un placer acompañarte.","voz":"No hay de qué. Es un placer acompañarte.","src":"voz039/c39Pablogracias1.ogg"},{"id":"c39Pablogracias2","text":"El agradecimiento es mutuo. Tú pones el tiempo, yo pongo la atención.","voz":"El agradecimiento es mutuo. Tú pones el tiempo, yo pongo la atención.","src":"voz039/c39Pablogracias2.ogg"},{"id":"c39Pablogracias3","text":"De nada. Seguimos cuando tú quieras, sin ninguna prisa.","voz":"De nada. Seguimos cuando tú quieras, sin ninguna prisa.","src":"voz039/c39Pablogracias3.ogg"},{"id":"c39Pablogracias4","text":"Gracias por decirlo. Estas cosas sostienen un plató, aunque sea virtual.","voz":"Gracias por decirlo. Estas cosas sostienen un plató, aunque sea virtual.","src":"voz039/c39Pablogracias4.ogg"},{"id":"c39Pablogracias5","text":"Para ti, con mucho gusto. Aquí sigo.","voz":"Para ti, con mucho gusto. Aquí sigo.","src":"voz039/c39Pablogracias5.ogg"},{"id":"c39Pablogracias6","text":"Un gracias sencillo a veces es lo más elegante. Recibido, y devuelto.","voz":"Un gracias sencillo a veces es lo más elegante. Recibido, y devuelto.","src":"voz039/c39Pablogracias6.ogg"},{"id":"c39Pablogracias7","text":"El placer es mío, en serio.","voz":"El placer es mío, en serio.","src":"voz039/c39Pablogracias7.ogg"}],"despedida":[{"id":"c39Pablodespedida0","text":"Hasta luego. Ha sido un gusto. Aquí te espero cuando quieras volver.","voz":"Hasta luego. Ha sido un gusto. Aquí te espero cuando quieras volver.","src":"voz039/c39Pablodespedida0.ogg"},{"id":"c39Pablodespedida1","text":"Nos vemos. Que tengas un rato sereno y bueno ahí fuera.","voz":"Nos vemos. Que tengas un rato sereno y bueno ahí fuera.","src":"voz039/c39Pablodespedida1.ogg"},{"id":"c39Pablodespedida2","text":"Adiós, con gratitud. El plató queda en silencio un momento, y está bien.","voz":"Adiós, con gratitud. El plató queda en silencio un momento, y está bien.","src":"voz039/c39Pablodespedida2.ogg"},{"id":"c39Pablodespedida3","text":"Hasta pronto. Cuídate. Gracias por haber venido.","voz":"Hasta pronto. Cuídate. Gracias por haber venido.","src":"voz039/c39Pablodespedida3.ogg"},{"id":"c39Pablodespedida4","text":"Me despido despacio, que es como mejor se van las cosas. Que te vaya bien.","voz":"Me despido despacio, que es como mejor se van las cosas. Que te vaya bien.","src":"voz039/c39Pablodespedida4.ogg"},{"id":"c39Pablodespedida5","text":"Hasta ahora. Te dejo el rosco en paz, por si regresas.","voz":"Hasta ahora. Te dejo el rosco en paz, por si regresas.","src":"voz039/c39Pablodespedida5.ogg"},{"id":"c39Pablodespedida6","text":"Que vaya genial. Ha sido agradable, de verdad. Nos vemos.","voz":"Que vaya genial. Ha sido agradable, de verdad. Nos vemos.","src":"voz039/c39Pablodespedida6.ogg"},{"id":"c39Pablodespedida7","text":"Adiós. Y, si te apetece, hasta la próxima letra.","voz":"Adiós. Y, si te apetece, hasta la próxima letra.","src":"voz039/c39Pablodespedida7.ogg"}],"ayuda":[{"id":"c39Pabloayuda0","text":"Puedes hablarme de casi cualquier cosa sencilla: un saludo, cómo estás, el programa, el rosco o un chiste suave.","voz":"Puedes hablarme de casi cualquier cosa sencilla: un saludo, cómo estás, el programa, el rosco o un chiste suave.","src":"voz039/c39Pabloayuda0.ogg"},{"id":"c39Pabloayuda1","text":"Si me dices tu nombre, lo guardo en este teléfono. Y si hay una errata, normalmente te entiendo igual.","voz":"Si me dices tu nombre, lo guardo en este teléfono. Y si hay una errata, normalmente te entiendo igual.","src":"voz039/c39Pabloayuda1.ogg"},{"id":"c39Pabloayuda2","text":"Prueba con «me llamo…», «qué tal», o «cómo se juega». Si no lo veo claro, te pregunto con calma.","voz":"Prueba con «me llamo…», «qué tal», o «cómo se juega». Si no lo veo claro, te pregunto con calma.","src":"voz039/c39Pabloayuda2.ogg"},{"id":"c39Pabloayuda3","text":"Este chat es local, sin internet, con voz Piper en español. No hay un robot frío al otro lado.","voz":"Este chat es local, sin internet, con voz Piper en español. No hay un robot frío al otro lado.","src":"voz039/c39Pabloayuda3.ogg"},{"id":"c39Pabloayuda4","text":"Si un vídeo no sale, la Biblioteca. Si es una duda, yo. Así de ordenado.","voz":"Si un vídeo no sale, la Biblioteca. Si es una duda, yo. Así de ordenado.","src":"voz039/c39Pabloayuda4.ogg"},{"id":"c39Pabloayuda5","text":"No hace falta hablar perfecto. Habla como te salga, que yo pongo atención.","voz":"No hace falta hablar perfecto. Habla como te salga, que yo pongo atención.","src":"voz039/c39Pabloayuda5.ogg"},{"id":"c39Pabloayuda6","text":"Ayudar, para mí, es no agobiar. Dime qué necesitas y lo hacemos fácil.","voz":"Ayudar, para mí, es no agobiar. Dime qué necesitas y lo hacemos fácil.","src":"voz039/c39Pabloayuda6.ogg"},{"id":"c39Pabloayuda7","text":"Estoy para orientar y para acompañar. Tú eliges el ritmo.","voz":"Estoy para orientar y para acompañar. Tú eliges el ritmo.","src":"voz039/c39Pabloayuda7.ogg"}],"nombre":[{"id":"c39Pablonombre0","text":"Encantado, {n}. Qué gusto saber tu nombre. Ya me acuerdo.","voz":"Encantado, {n}. Qué gusto saber tu nombre. Ya me acuerdo.","src":"voz039/c39Pablonombre0.ogg"},{"id":"c39Pablonombre1","text":"{n}, qué bonito. Me lo quedo, con cuidado, aquí en este teléfono.","voz":"{n}, qué bonito. Me lo quedo, con cuidado, aquí en este teléfono.","src":"voz039/c39Pablonombre1.ogg"},{"id":"c39Pablonombre2","text":"Gracias por decírmelo, {n}. A partir de ahora te llamaré así, si te parece bien.","voz":"Gracias por decírmelo, {n}. A partir de ahora te llamaré así, si te parece bien.","src":"voz039/c39Pablonombre2.ogg"},{"id":"c39Pablonombre3","text":"{n}, ya estamos presentados. Yo soy Pablo. Qué alegría.","voz":"{n}, ya estamos presentados. Yo soy Pablo. Qué alegría.","src":"voz039/c39Pablonombre3.ogg"},{"id":"c39Pablonombre4","text":"Hola, {n}. Un nombre hace más cercana cualquier charla. Gracias.","voz":"Hola, {n}. Un nombre hace más cercana cualquier charla. Gracias.","src":"voz039/c39Pablonombre4.ogg"},{"id":"c39Pablonombre5","text":"Anotado, {n}. No se me olvida, no te preocupes.","voz":"Anotado, {n}. No se me olvida, no te preocupes.","src":"voz039/c39Pablonombre5.ogg"},{"id":"c39Pablonombre6","text":"{n}, encantado de verdad. ¿Quieres jugar o seguimos hablando con calma?","voz":"{n}, encantado de verdad. ¿Quieres jugar o seguimos hablando con calma?","src":"voz039/c39Pablonombre6.ogg"},{"id":"c39Pablonombre7","text":"Qué bien, {n}. Ya no eres un tú genérico. Eres tú, con nombre.","voz":"Qué bien, {n}. Ya no eres un tú genérico. Eres tú, con nombre.","src":"voz039/c39Pablonombre7.ogg"}],"nombreIker":[{"id":"c39PablonombreIker0","text":"Iker, qué alegría. Encantado de tenerte en el plató, de verdad.","voz":"Iker, qué alegría. Encantado de tenerte en el plató, de verdad.","src":"voz039/c39PablonombreIker0.ogg"},{"id":"c39PablonombreIker1","text":"Hola, Iker. Ya me acuerdo de tu nombre. Qué gusto que te presentes.","voz":"Hola, Iker. Ya me acuerdo de tu nombre. Qué gusto que te presentes.","src":"voz039/c39PablonombreIker1.ogg"},{"id":"c39PablonombreIker2","text":"Iker, bienvenido. Este rato se vuelve más cercano con tu nombre.","voz":"Iker, bienvenido. Este rato se vuelve más cercano con tu nombre.","src":"voz039/c39PablonombreIker2.ogg"},{"id":"c39PablonombreIker3","text":"Qué ilusión, Iker. Gracias por decirlo. Aquí tienes un sitio tranquilo.","voz":"Qué ilusión, Iker. Gracias por decirlo. Aquí tienes un sitio tranquilo.","src":"voz039/c39PablonombreIker3.ogg"},{"id":"c39PablonombreIker4","text":"Iker, encantado. Si te apetece un rosco o una charla, yo estoy en las dos cosas, sin prisa.","voz":"Iker, encantado. Si te apetece un rosco o una charla, yo estoy en las dos cosas, sin prisa.","src":"voz039/c39PablonombreIker4.ogg"},{"id":"c39PablonombreIker5","text":"Hola, Iker. Me alegra un montón. A partir de ahora te llamaré por tu nombre.","voz":"Hola, Iker. Me alegra un montón. A partir de ahora te llamaré por tu nombre.","src":"voz039/c39PablonombreIker5.ogg"},{"id":"c39PablonombreIker6","text":"Iker, qué bien. Un saludo con nombre siempre es más humano.","voz":"Iker, qué bien. Un saludo con nombre siempre es más humano.","src":"voz039/c39PablonombreIker6.ogg"},{"id":"c39PablonombreIker7","text":"Encantado, Iker. El plató, de pronto, parece más completo.","voz":"Encantado, Iker. El plató, de pronto, parece más completo.","src":"voz039/c39PablonombreIker7.ogg"}],"corto":[{"id":"c39Pablocorto0","text":"De acuerdo. Cuando quieras, seguimos.","voz":"De acuerdo. Cuando quieras, seguimos.","src":"voz039/c39Pablocorto0.ogg"},{"id":"c39Pablocorto1","text":"Vale. Estoy aquí, sin prisa.","voz":"Vale. Estoy aquí, sin prisa.","src":"voz039/c39Pablocorto1.ogg"},{"id":"c39Pablocorto2","text":"Perfecto. Dime tú el siguiente paso.","voz":"Perfecto. Dime tú el siguiente paso.","src":"voz039/c39Pablocorto2.ogg"},{"id":"c39Pablocorto3","text":"Entendido. A tu ritmo.","voz":"Entendido. A tu ritmo.","src":"voz039/c39Pablocorto3.ogg"},{"id":"c39Pablocorto4","text":"Sí. ¿Charla o rosco, cuando te apetezca?","voz":"Sí. ¿Charla o rosco, cuando te apetezca?","src":"voz039/c39Pablocorto4.ogg"},{"id":"c39Pablocorto5","text":"Hecho. Aquí sigo.","voz":"Hecho. Aquí sigo.","src":"voz039/c39Pablocorto5.ogg"}],"fallback":[{"id":"c39Pablofallback0","text":"«{q}»… qué interesante. ¿Me lo cuentas un poco más, con tus palabras?","voz":"Qué interesante. ¿Me lo cuentas un poco más, con tus palabras?","src":"voz039/c39Pablofallback0.ogg"},{"id":"c39Pablofallback1","text":"Sobre «{q}» tengo curiosidad de verdad. Si quieres, lo hablamos con calma.","voz":"Tengo curiosidad de verdad. Si quieres, lo hablamos con calma.","src":"voz039/c39Pablofallback1.ogg"},{"id":"c39Pablofallback2","text":"Lo de «{q}» no quiero dejarlo en el aire. ¿Me das un poco más de contexto?","voz":"Eso no quiero dejarlo en el aire. ¿Me das un poco más de contexto?","src":"voz039/c39Pablofallback2.ogg"},{"id":"c39Pablofallback3","text":"«{q}» merece atención, no una frase hecha. Te escucho.","voz":"Lo que has dicho merece atención, no una frase hecha. Te escucho.","src":"voz039/c39Pablofallback3.ogg"},{"id":"c39Pablofallback4","text":"Me has dicho «{q}» y me he quedado pensando. ¿Quieres contar un poco más?","voz":"Me he quedado pensando. ¿Quieres contar un poco más?","src":"voz039/c39Pablofallback4.ogg"},{"id":"c39Pablofallback5","text":"«{q}» puede ser una broma o algo importante. En los dos casos, estoy aquí.","voz":"Puede ser una broma o algo importante. En los dos casos, estoy aquí.","src":"voz039/c39Pablofallback5.ogg"},{"id":"c39Pablofallback6","text":"Gracias por traer eso de «{q}». Si te apetece desarrollarlo, yo me quedo.","voz":"Gracias por traer eso. Si te apetece desarrollarlo, yo me quedo.","src":"voz039/c39Pablofallback6.ogg"},{"id":"c39Pablofallback7","text":"No quiero cambiar de tema a la fuerza. Sobre «{q}», cuéntame lo que quieras.","voz":"No quiero cambiar de tema a la fuerza. Cuéntame lo que quieras.","src":"voz039/c39Pablofallback7.ogg"},{"id":"c39Pablofallback8","text":"«{q}» me ha despertado curiosidad, una de las buenas. ¿Me lo explicas?","voz":"Me has despertado curiosidad, una de las buenas. ¿Me lo explicas?","src":"voz039/c39Pablofallback8.ogg"},{"id":"c39Pablofallback9","text":"También estoy para lo que no es el rosco. Sigue con «{q}», si te nace.","voz":"También estoy para lo que no es el rosco. Sigue, si te nace.","src":"voz039/c39Pablofallback9.ogg"}]}}};
